/* APS Field App – Handbook scenarios (data only). Add a scenario by pushing one more object onto APS_SCENARIOS.
   Shape:
   { id, cat:'geysers' (one or more category ids, comma separated), title, kw:'search words incl. synonyms / Afrikaans / site slang', sym:'symptom phrases people say', sum:'one line',
     diagnose:{ start:'q1', nodes:{ q1:{q:'Question?', hint:'optional', opts:[['Label','nextNodeId'],...]},
                                    r1:{res:1, cause:'Likely cause', why:'optional', do:['what to do',...], parts:[['Button label','parts search words']], call:'electrician|gas|plumber|municipality' (optional red call-out), next:'repair' (optional jump to a tab)} } },
     repair:{ head:'optional list heading', warn:['red warning',...], tools:[...], parts:[[label,query],...], steps:['tick-box step',...], sans:['guide-only standard notes',...], see:['scenario-id','tab','Button label'] },
     install:{ ...same as repair... },
     labels:{ repair:'Checklist' } (optional tab names) }
   Standards named here are for orientation only. Every page shows "Guide only - check the current standard". */
var APS_GOF='Guide only \u2013 check the current standard';
var APS_CALLS={electrician:'Call a registered electrician. Electrical work on a geyser needs an Electrical Certificate of Compliance (CoC).',gas:'Call a registered gas installer. Gas work needs a gas Certificate of Conformity (CoC). Do not repair gas appliances yourself.',plumber:'This needs a licensed (PIRB) plumber.',municipality:'Report it to the municipality / water department.'};
var ELEC_WARN='Geyser wiring, elements and thermostats: a registered electrician only (Electrical CoC). A plumber isolates and makes safe at the DB, tests it is dead, and never switches on a geyser that is not full of water.';
var GAS_WARN='Gas appliances, gas pipework, flues and cylinders: a registered gas installer only (gas Certificate of Conformity). If you smell gas: no flames, no switches, open windows, close the cylinder valve if it is safe, leave and call the installer or emergency services.';
var HOT_WARN='Hot water scalds in seconds. Let the geyser and pipes cool or draw off the hot water first, and drain to a safe place. Open a hot tap before undoing a joint on a hot line.';
var HYG_WARN='Sewage: wear waterproof gloves and glasses, keep cuts covered, wash well afterwards. Never enter a manhole or sewer chamber (gas).';
var APS_CATS=[['geysers','Geysers & hot water'],['taps','Taps & mixers'],['toilets','Toilets'],['drainage','Drainage & sewer'],['leaks','Leaks & pipes'],['pressure','Pressure & pumps'],['bath','Bathrooms & showers'],['kitchen','Kitchen & appliances'],['outdoor','Outdoor, irrigation & borehole'],['solar','Solar, heat pump & gas'],['emergency','Emergencies'],['install','Installations / new work'],['compliance','Compliance & paperwork']];
var APS_SCENARIOS=[
{id:'geyser-not-heating',title:'Geyser not heating properly',cat:'geysers',kw:'geyser not heating hot water cold lukewarm element thermostat trip breaker isolator timer prv valves sediment solar gas heat pump runs out geiser warm water nie warm nie lukewarm tripping no hot water',sum:'Electric geyser: no heat, lukewarm, or runs out fast',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is the problem with the hot water?',hint:'Start with the one that matches best.',opts:[['No hot water at all (cold at every hot tap)','q_pow'],['Hot, but runs out fast or never gets really hot','q_size'],['Hot flow is weak (trickle) but hot enough','r_flow'],['Hot at some taps, not at one tap','r_tap'],['It is a solar, heat pump, gas or instant geyser','q_var']]},
  q_pow:{q:'Check the DB board. Is the geyser breaker ON and the geyser isolator switch (if any) ON?',hint:'Look only. Never open the geyser cover or touch wiring.',opts:[['Breaker is OFF or has tripped','q_trip'],['Breaker and isolator are ON','q_grid'],['Whole house has no power','r_grid']]},
  q_trip:{q:'Is the DB dry and is there no burning smell? Reset the breaker ONCE. Does it trip again?',opts:[['It trips again (immediately or within hours)','r_earth'],['It stays on','r_onceok'],['Wet DB, burning smell, or hot cables','r_danger']]},
  q_grid:{q:'Is there a geyser timer, smart controller (e.g. Geyserwise) or load-control box fitted?',opts:[['Yes','r_timer'],['No / not sure','q_full']]},
  q_full:{q:'Is the geyser full of water? (Cold taps run, geyser isolating valve is open, no leak or wet drip tray.)',opts:[['No: valve closed, supply off, or leaking','r_empty'],['Yes, it is full','q_pipe']]},
  q_pipe:{q:'Feel the hot outlet pipe coming out of the geyser (carefully, back of the hand). Is it hot?',opts:[['Hot at the geyser but cold at the taps','r_pipe'],['Cold or barely warm at the geyser','r_element']]},
  q_size:{q:'How long has it been like this?',opts:[['Always (more people, bigger demand)','r_size'],['Slowly got worse over months','q_age'],['Suddenly, after a power cut, trip or timer change','q_pow'],['Water is hot but not hot enough','q_thermo']]},
  q_age:{q:'Is the geyser older than about 7 years, or is the water very hard (white scale on taps and kettles)?',opts:[['Yes','r_scale'],['No','q_loss']]},
  q_loss:{q:'Is any hot tap dripping, is there a long uninsulated hot pipe, or are hot pipes in a cold roof or outside wall?',opts:[['Yes','r_loss'],['No','r_element']]},
  q_thermo:{q:'Has anyone changed the temperature setting, or does a smart controller or timer limit the temperature?',opts:[['Yes / maybe','r_setting'],['No','r_thermo']]},
  q_var:{q:'Which type is it?',opts:[['Solar (roof panel, tank above or below)','r_solar'],['Heat pump','r_hp'],['Gas','r_gas'],['Instant (tankless, electric)','r_inst']]},
  r_grid:{res:1,cause:'No power to the property',do:['Check if the neighbours have power (outage or load shedding).','Check the main breaker and earth-leakage switch at the DB. Reset it once only.','If only your house is off and it will not reset, call the electrician or Eskom / municipality.'],call:'electrician'},
  r_earth:{res:1,cause:'Likely an electrical fault on the geyser circuit (failed element or thermostat, wet or burnt wiring)',why:'A breaker that keeps tripping is protecting someone. Do not keep resetting it and do not bypass it.',do:['Leave the geyser breaker OFF and label it: "Do not switch on - fault".','Tell the customer why they have no hot water.','Book a registered electrician to test the element, thermostat and wiring.','Plumber: check the drip tray and safety-valve drain for water leaking onto the electrics.'],call:'electrician',parts:[['Element','geyser element'],['Thermostat','geyser thermostat']],next:'repair'},
  r_onceok:{res:1,cause:'A one-off trip (overload, power surge or a load-shedding spike)',do:['Watch the geyser for the next day. Check hot water is back within a few hours.','If it trips again, treat it as an electrical fault and call an electrician.','Ask about a surge protector or load-control box if it keeps happening after power returns.'],next:'repair'},
  r_danger:{res:1,cause:'Unsafe electrics',do:['Do not touch the DB or the geyser wiring.','Switch off at the main breaker only if you can do it without touching wet or damaged parts.','Tell the customer. Keep everyone away.','Call a registered electrician now.'],call:'electrician'},
  r_timer:{res:1,cause:'Timer or controller is off, in the wrong time slot or faulty',do:['Check the timer / controller display and the schedule. Make sure the ON period is long enough for the geyser size.','Check the controller has power and the right time and date.','Ask the electrician to bypass the controller to prove whether the geyser itself heats.','A smart controller can also block heating. Check its app or settings.'],call:'electrician',next:'repair'},
  r_empty:{res:1,cause:'The geyser is empty or isolated. A dry geyser must not be switched on (the element burns out)',do:['Switch the geyser OFF at the DB first.','Open the geyser cold-feed isolating valve fully.','Open a hot tap in the house until water runs without air.','Look for leaks on the geyser, pipes and drip tray. A leaking cylinder means replacement.','Only when the geyser is full: switch the power back on.'],parts:[['Isolating valve','ball valve 22mm']],next:'repair'},
  r_pipe:{res:1,cause:'Hot water is not reaching the taps: closed valve, airlock, blocked non-return valve or mixer fault',do:['Check any isolating valve on the hot outlet.','Open the hot tap fully and bleed air.','Check mixer cartridges, flexi hoses and crossed hot / cold connections at the problem taps.','Check for a faulty non-return or pressure control valve on the supply (hot flow weak everywhere).'],parts:[['Flexi hose','flexi'],['Cartridge','cartridge']],next:'repair'},
  r_element:{res:1,cause:'Failed element, or the thermostat / thermal cut-out has tripped',why:'The geyser has water and power but stays cold. These are the usual reasons. Only a test can tell which.',do:['Electrician: check the power at the geyser, then test the element and thermostat. Some thermostats have a manual reset button after overheating. Do not press it before the cause is known.','Replace a failed element or thermostat (see Repair).','Check the tank for scale or sludge when it is drained.','If the cylinder is old and leaking or corroded, quote a new geyser instead.'],call:'electrician',parts:[['Element','geyser element'],['Thermostat','geyser thermostat'],['Gasket','geyser gasket']],next:'repair'},
  r_size:{res:1,cause:'The geyser is too small for the demand',do:['Count people, showers and baths a day. A 150 L geyser suits about 2 to 3 people; larger families need 200 to 300 L.','Check the real size and rating on the data plate.','Quote a bigger geyser, a second geyser, or a solar / heat-pump option.','Use a timer so the geyser reheats before peak use.'],parts:[['Geyser','geyser 150l']],next:'install'},
  r_scale:{res:1,cause:'Scale or sludge on the element, or an old element',do:['Flush the geyser (drain through the drain cock to a safe place).','Electrician: check the element. A scaled element is replaced, not cleaned.','Check the sacrificial anode and replace it if used up.','In hard-water areas, use an element made for hard water.','If the cylinder is corroded or leaking, replace the geyser.'],parts:[['Element (hard water)','element hard water'],['Anode','anode'],['Gasket','geyser gasket']],next:'repair'},
  r_loss:{res:1,cause:'Hot water is being lost or cooled before it is used',do:['Fix any dripping hot tap or leaking hot pipe. One drip can waste a lot of hot water.','Insulate hot pipes and the geyser as required.','Check the thermostat setting (about 60 \u00B0C).','Shorten very long runs where practical (a hot-water loop or a second small geyser).'],parts:[['Pipe lagging','lagging'],['Tap cartridges','cartridge']],next:'repair'},
  r_setting:{res:1,cause:'The temperature setting or the controller schedule is limiting heat',do:['Ask who changed it and when.','Electrician sets the thermostat (about 60 \u00B0C) or reviews the smart controller settings.','Do not set it lower than about 60 \u00B0C. Lower temperatures allow bacteria to grow in the tank.'],call:'electrician'},
  r_thermo:{res:1,cause:'A faulty thermostat or element',do:['Electrician tests the thermostat and element.','Replace what has failed (see Repair).','While the geyser is drained, check for scale and the anode.'],call:'electrician',parts:[['Thermostat','geyser thermostat'],['Element','geyser element']],next:'repair'},
  r_flow:{res:1,cause:'Restricted supply to the geyser or the hot side',do:['Check the cold feed isolating valve is fully open.','Check the non-return valve, pressure control valve and any strainer for blockage.','Check the hot water pipe size and any partly closed valve.','Remove and clean the aerator or shower head at the taps.','Measure supply pressure with a gauge at an outside tap.'],parts:[['Pressure control valve','pressure control valve'],['Non-return valve','non return valve']],next:'repair'},
  r_tap:{res:1,cause:'A problem at that tap only',do:['Check the mixer cartridge and the flexi hoses.','Check hot and cold are not crossed.','Check the angle valves are fully open.','Clean the aerator.'],parts:[['Cartridge','cartridge'],['Flexi hose','flexi'],['Angle valve','angle valve']]},
  r_solar:{res:1,cause:'Solar system: weather, panel, pump, controller or the electric back-up element',do:['Check the weather and season. Solar is weaker on cloudy or winter days.','Check the electric back-up (the same checks as an electric geyser: breaker, thermostat, element).','Check the circulation pump and controller (pumped systems) for power and error lights.','Check the panels are clean and not shaded, and look for leaks or air in the system.','Call the solar installer for the panels, pump or controller.'],call:'electrician'},
  r_hp:{res:1,cause:'Heat pump: controller, fan or compressor fault, or a lockout',do:['Check the display for an error code and write it down.','Check power supply and breaker.','Check the air inlet and outlet are clear and the filter is clean.','Call the heat pump installer or the maker with the code.'],call:'electrician'},
  r_gas:{res:1,cause:'Gas geyser: gas supply, ignition, flue or water-flow fault',do:['Check the gas bottle or supply is not empty and the gas valve is open.','If you smell gas: open windows, do not use switches or flames, shut off the gas, leave, and call the gas installer.','Do not open or repair gas appliances yourself.'],call:'gas'},
  r_inst:{res:1,cause:'Instant electric heater: low flow, scaled heating parts, tripped protection or an undersized supply',do:['Check the flow is above the heater\u2019s minimum. Clean aerators and filters.','Check the breaker and the cable size rating with an electrician.','Check for scale in hard-water areas.','Electrician checks the heater itself.'],call:'electrician'}
 }},
 repair:{warn:[ELEC_WARN],tools:['Torch / head-lamp','Hose pipe and bucket','Ladder (roof-space access)','Pressure gauge','Element spanner (electrician)','Multimeter (electrician)','PTFE tape','New gasket / seal','Camera (data plate and photos)'],
  parts:[['Geyser element','geyser element'],['Thermostat','geyser thermostat'],['Flange gasket','geyser gasket'],['Anode','anode'],['Pressure control valve','pressure control valve'],['Vacuum breaker','vacuum breaker'],['Safety valve','safety valve'],['Drain cock','drain cock']],
  steps:['Photograph the data plate (litres, kPa rating, element kW). Write down the fault you found with the Diagnose tab.','Switch the geyser OFF at the DB and at the isolator. Label it "Do not switch on". Test it is dead (electrician).','Close the cold-feed isolating valve. Open a hot tap in the house to let pressure out and air in.','Drain the geyser through the drain cock or a hose to a safe place. The water may be scalding: let it cool or draw hot water off first.','Electrician removes the cover, disconnects the wires and removes the element (element spanner). Photograph the wiring before disconnecting.','Look inside the tank and at the old element. Heavy scale or sludge: flush with the cold feed until the water runs clear. Check the anode.','Fit the new element or thermostat of the same type, rating and length, with a new gasket / seal. Do not over-tighten.','Close the drain. Open the cold-feed valve and fill with a hot tap open until water runs steadily without air. Close the tap.','Check the flange, element joint and every pipe joint for leaks while the geyser is filling.','Only when the geyser is FULL: the electrician reconnects, tests, sets the thermostat (usually about 60 \u00B0C) and gives the Electrical CoC.','Check the safety-valve drain and tray: no drips, discharge visible. Briefly lift the valve lever (water must flow, then stop).','Check hot water at the tap after a few hours. Take photos. Tell the customer what was found.'],
  sans:['SANS 10254 covers fixed electric storage water heaters: valves, drip tray, safety (T&P) valve and its drain pipe.','Safety valve drain: metal, at least the valve outlet size, continuous fall with no upward sections, no more than 3 bends, discharging where it can be seen, and with no valve, cap or plug in it.','Vacuum breaker(s) above the top of the geyser; isolating and non-return valves on the cold feed; a pressure control valve where supply pressure is above the geyser rating.','The wiring code for the electrical part is SANS 10142-1. The electrician issues the Electrical CoC.']},
 install:{see:['geyser-install','install','Open "Geyser installation" for the full replacement steps'],warn:['If the cylinder is leaking or corroded, repair is not possible. The geyser must be replaced.'],
  steps:['Compare the repair cost with the age of the geyser. After about 8 to 10 years, or with a leaking cylinder, quote a replacement.','Check the data plate for size and pressure rating so the replacement matches the demand.','Follow the Geyser installation scenario.'],
  parts:[['Geyser','geyser 150l'],['Geyser tray','geyser tray']],
  sans:['Replacement of a geyser normally needs a plumbing CoC from a licensed plumber and an Electrical CoC from an electrician. Insurers often ask for them.']}},
{id:'no-hot-water',title:'No hot water',cat:'geysers',kw:'no hot water cold geyser breaker tripped timer isolating valve mixer geiser geen warm water cold shower breaker',sum:'First checks when nothing is hot',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Is the water cold at ALL hot taps in the house?',opts:[['Yes, every hot tap','q2'],['Only one tap or one bathroom','r_tap']]},
  q2:{q:'Is there normal cold water pressure at the taps?',opts:[['Yes, cold water is fine','q3'],['No water or very low','r_water']]},
  q3:{q:'Is the geyser breaker (and isolator, if any) ON at the DB?',hint:'Look, do not touch wiring.',opts:[['OFF or tripped','r_trip'],['ON','q4'],['Whole house has no power','r_grid']]},
  q4:{q:'Is there a timer or smart controller on the geyser?',opts:[['Yes','r_timer'],['No / not sure','q5']]},
  q5:{q:'Is the geyser leaking or is the drip tray wet, or is the cold-feed isolating valve closed?',opts:[['Yes','r_empty'],['No, all dry and open','r_elec']]},
  r_tap:{res:1,cause:'Mixer, cartridge, flexi hose or crossed hot / cold at that tap',do:['Check the angle valves are open.','Check the flexi hoses and cartridge.','Clean the aerator.'],parts:[['Cartridge','cartridge'],['Flexi hose','flexi']]},
  r_water:{res:1,cause:'A water supply problem, not a geyser problem',do:['Check the municipal supply and the main valve.','Check the meter and the pressure control valve.'],next:'repair'},
  r_trip:{res:1,cause:'The geyser circuit has tripped or been switched off',do:['Reset the breaker once only (dry DB, no burning smell).','If it trips again, leave it off and call an electrician. Do not keep resetting.','Check the drip tray and wiring for water.'],call:'electrician',next:'repair'},
  r_grid:{res:1,cause:'No power to the property',do:['Check for a local outage or load shedding.','Check the main breaker and earth-leakage switch at the DB.'],call:'electrician'},
  r_timer:{res:1,cause:'Timer or controller is off or in the wrong time slot',do:['Check the schedule and the time on the controller.','Ask the electrician to bypass it to test the geyser.'],call:'electrician',next:'repair'},
  r_empty:{res:1,cause:'The geyser is empty or isolated, or leaking',do:['Switch the geyser off at the DB.','Open the cold-feed isolating valve.','Open a hot tap until water runs without air. Only then switch on.','If the cylinder is leaking, it has to be replaced.'],next:'repair'},
  r_elec:{res:1,cause:'Failed element or thermostat (water and power are fine)',do:['Electrician tests the element and thermostat.','Replace the part that failed.'],call:'electrician',parts:[['Element','geyser element'],['Thermostat','geyser thermostat']],next:'repair'}
 }},
 repair:{warn:[ELEC_WARN],tools:['Torch','Hose and bucket','PTFE tape','Camera'],steps:['Confirm the geyser is full: open a hot tap and check water runs without air.','Check the cold-feed isolating valve is fully open.','Check the breaker and isolator at the DB. Reset a tripped breaker once only.','Check the timer or controller.','Look for leaks at the geyser, pipes and drip tray.','If the geyser has power and water but stays cold, book the electrician to test the element and thermostat.','After the fix, check hot water at a tap after a few hours and tell the customer what was found.'],
  parts:[['Isolating valve','ball valve 22mm'],['Geyser element','geyser element'],['Thermostat','geyser thermostat']],sans:['Never switch on a geyser that is not full of water: the element burns out.','Reconnection of the geyser to power after repairs is for a registered electrician (Electrical CoC).'],see:['geyser-not-heating','diagnose','More detail: "Geyser not heating properly"']}},
{id:'low-pressure',title:'Low water pressure',cat:'pressure',kw:'low pressure weak flow trickle slow isolating valve blocked aerator pressure control valve galvanised lae druk swak water trickle weak flow kraan',sum:'Weak flow at one tap, hot only, or the whole house',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Where is the pressure low?',opts:[['Every tap, hot and cold','q_all'],['Only hot water','r_hot'],['One tap or shower only','r_one'],['Only at certain times of day','r_peak']]},
  q_all:{q:'Is the outside tap at the street or meter also weak?',opts:[['Yes, weak at the meter too','r_muni'],['No, strong at the meter','q_pipes']]},
  q_pipes:{q:'Is the house old, with galvanised pipes, or has a valve or pressure control valve been fitted recently?',opts:[['Old galvanised pipes','r_galv'],['New valve or PCV work','r_valve'],['No change, got worse slowly','r_scale']]},
  r_hot:{res:1,cause:'Restricted geyser valves or hot pipe',do:['Check the non-return valve, pressure control valve and strainer on the geyser supply.','Check the isolating valve is fully open.','Check pipe size and any kinks.'],parts:[['Pressure control valve','pressure control valve'],['Non-return valve','non return valve']],next:'repair'},
  r_one:{res:1,cause:'Blocked aerator, shower head, flexi hose or partly closed angle valve',do:['Unscrew and clean the aerator or shower head (vinegar for scale).','Replace the flexi hose if it is kinked or blocked.','Open the angle valve fully.','Check the cartridge.'],parts:[['Flexi hose','flexi'],['Angle valve','angle valve'],['Shower head','shower head']],next:'repair'},
  r_peak:{res:1,cause:'Peak demand in the area',do:['Test with a pressure gauge in the morning, afternoon and evening.','If it drops a lot, quote a tank with a booster pump.'],parts:[['Pressure gauge','pressure gauge']]},
  r_muni:{res:1,cause:'Low supply from the municipality or a faulty water meter or main valve',do:['Check the meter valve and stop-cock are fully open.','Check the meter strainer.','If everyone in the street has it, report it to the municipality.'],call:'municipality'},
  r_galv:{res:1,cause:'Corroded galvanised pipe (scale narrows the bore)',do:['Cut a section open and look inside.','Quote replacing the pipe in copper, PEX or multilayer.'],parts:[['Copper pipe 22mm','copper pipe 22mm'],['Multilayer pipe','multilayer pipe']]},
  r_valve:{res:1,cause:'A valve that is partly closed, set wrong or blocked',do:['Open the isolating valves fully.','Check the PCV setting and clean its strainer.','Check the flow direction arrow on every valve.'],parts:[['Pressure control valve','pressure control valve']],next:'repair'},
  r_scale:{res:1,cause:'Scale or sediment building up in pipes or valves',do:['Flush the system.','Check the strainers and valves.','If it gets worse, camera or cut-out inspection and a quote to replace the worst pipe.'],next:'repair'}
 }},
 repair:{tools:['Pressure gauge (with hose tap adaptor)','Spanners','PTFE tape','Bucket','Pipe cutter'],parts:[['Flexi hose','flexi'],['Angle valve','angle valve'],['Pressure control valve','pressure control valve'],['Shower head','shower head']],
  steps:['Fit the pressure gauge to an outside tap with all taps closed. Note the static pressure.','Open a tap and note the pressure while water runs. A big drop shows a restriction.','Test at the meter side and at the house side to find where it drops.','Clean aerators and shower heads. Replace blocked flexi hoses.','Open all isolating valves fully. Clean strainers in valves.','Replace a faulty pressure control valve. Set it to the geyser rating.','Retest the pressure and flow. Write the readings down for the customer.'],
  sans:['SANS 10252-1 covers water installations. Typical domestic supply pressure is roughly 100 to 400 kPa. Check geyser and fitting ratings before setting a PCV.']}},
{id:'leaking-tap',title:'Leaking tap',cat:'taps',kw:'leaking tap dripping drip washer cartridge o-ring spindle basin mixer bibcock kraan lek drup dripping tap washer',sum:'Drip from the spout, base or handle',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Where does it leak from?',opts:[['Drips from the spout when closed','q_type'],['Water at the base or around the handle','r_oring'],['Under the basin or sink (pipes and hoses)','r_under'],['Outside tap or garden tap','r_out']]},
  q_type:{q:'What kind of tap is it?',opts:[['Old style with two separate taps (washer type)','r_washer'],['Quarter-turn / ceramic disc tap','r_disc'],['Single-lever mixer','r_cart']]},
  r_washer:{res:1,cause:'Worn tap washer or seat',do:['Close the angle valve, open the tap to empty it.','Remove the head, replace the washer. If the seat is pitted, reface or replace it.','Reassemble and test.'],parts:[['Tap washers','tap washer'],['Tap seat','tap seat']],next:'repair'},
  r_disc:{res:1,cause:'Worn ceramic disc / cartridge',do:['Close the water. Remove the head and unscrew the cartridge.','Replace with the same type and length.'],parts:[['Quarter-turn cartridge','cartridge']],next:'repair'},
  r_cart:{res:1,cause:'Worn mixer cartridge',do:['Close the angle valves. Remove the lever, cap and retaining nut.','Replace the cartridge (match 35 mm or 40 mm size and make).','Check the seals and the aerator.'],parts:[['Mixer cartridge','mixer cartridge'],['Basin mixer','basin mixer']],next:'repair'},
  r_oring:{res:1,cause:'Worn spindle seal or O-ring, or a loose gland nut',do:['Close the water. Remove the handle or lever.','Replace the O-ring or gland packing. Tighten the gland nut gently.'],parts:[['O-rings','o-ring'],['Cartridge','cartridge']],next:'repair'},
  r_under:{res:1,cause:'Leaking flexi hose, angle valve or trap joint',do:['Dry everything and watch to find the wet joint.','Replace a leaking flexi hose or angle valve.','Remake trap joints with good seals.'],parts:[['Flexi hose','flexi'],['Angle valve','angle valve'],['Basin trap','basin trap']],next:'repair'},
  r_out:{res:1,cause:'Worn washer or spindle on an outside tap, or a damaged tap',do:['Close the water to the tap. Replace the washer or the bibcock.','Fit a vacuum breaker or a check valve where required.'],parts:[['Bibcock','bibcock'],['Vacuum breaker','vacuum breaker']],next:'repair'}
 }},
 repair:{tools:['Adjustable spanner','Basin spanner','Screwdrivers','Allen keys','Bucket and towel','PTFE tape','Spare washers and O-rings'],parts:[['Cartridge','cartridge'],['Tap washer','tap washer'],['Flexi hose','flexi'],['Angle valve','angle valve']],
  steps:['Close the angle valve under the basin or sink. If there is none, close the room valve or the main and fit angle valves.','Open the tap to release pressure and empty the line.','Put the plug in or a cloth over the drain so small parts do not fall in.','Remove the handle, cap and retaining nut. Take the old cartridge or washer with you to match the new one.','Clean the seat and the body. Fit the new washer or cartridge with grease on the seals.','Reassemble. Do not over-tighten (ceramic cracks).','Open the angle valve slowly. Check the spout, the base and every joint for leaks. Wipe dry and check again after 10 minutes.'],
  sans:['SANS 10252-1: an isolating (angle) valve at each fixture makes repairs easier and is good practice.']}},
{id:'running-toilet',title:'Running toilet',cat:'toilets',kw:'running toilet cistern float valve fill flush valve seal inlet leaking wc overflow phantom flush toilet runs on keeps filling will not stop toilet lekkasie',sum:'Water keeps running or trickling into the bowl',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What happens?',opts:[['Water trickles into the bowl all the time','q_dye'],['Water runs into the overflow pipe','r_float'],['Cistern fills very slowly','r_slow'],['Toilet flushes by itself now and then','r_dye'],['Water on the floor','r_floor']]},
  q_dye:{q:'Put food colouring in the cistern. After 10 minutes, is there colour in the bowl without flushing?',opts:[['Yes, colour in the bowl','r_dye'],['No colour. Water level is too high','r_float']]},
  r_dye:{res:1,cause:'Flush valve seal (washer) is perished or dirty',do:['Close the angle valve and flush to empty the cistern.','Clean the seat. Replace the flush valve seal or the whole flush valve.'],parts:[['Flush valve','flush valve'],['Cistern washer','cistern washer']],next:'repair'},
  r_float:{res:1,cause:'Fill valve (float) set too high or faulty',do:['Adjust the float so the water stops about 25 mm below the overflow.','Replace the fill valve if it will not shut off.'],parts:[['Fill valve','fill valve'],['Float valve','float valve']],next:'repair'},
  r_slow:{res:1,cause:'Blocked inlet filter, partly closed angle valve, or a worn fill valve',do:['Check the angle valve is fully open.','Clean the inlet filter on the fill valve.','Replace the fill valve if the flow is still weak.'],parts:[['Fill valve','fill valve'],['Angle valve','angle valve']],next:'repair'},
  r_floor:{res:1,cause:'Leaking cistern connection, cracked cistern or loose flexi hose',do:['Dry everything and watch to find the wet joint.','Check the flexi hose, the angle valve and the cistern inlet nut.','Check the cistern to pan seal and the flush pipe.','A cracked cistern or pan must be replaced.'],parts:[['Flexi hose','flexi'],['Cistern seal','cistern seal']],next:'repair'}
 }},
 repair:{tools:['Adjustable spanner','Screwdrivers','Sponge and bucket','Food colouring','PTFE tape','Spare seals'],parts:[['Fill valve','fill valve'],['Flush valve','flush valve'],['Flexi hose','flexi'],['Angle valve','angle valve']],
  steps:['Close the angle valve behind the toilet. Flush to empty the cistern. Sponge out the rest.','Take photos of how the old parts fit (cistern models differ).','Replace the faulty part: fill valve, flush valve or seal. Match the brand and model where possible.','Reconnect the water. Set the water level about 25 mm below the overflow.','Flush several times. Check the shut-off, the flush volume and every joint for leaks.','Check the cistern to pan connection and the flexi hose are dry. Wipe and check again after 10 minutes.'],
  sans:['SANS 10252-1: cisterns must have an overflow that discharges safely and a fill valve that stops the inflow.','A running toilet can waste a large volume of water in a day. Tell the customer.']}},
{id:'blocked-drain',title:'Blocked drain or gully',cat:'drainage',kw:'blocked drain gully slow drain rodding eye rods jetter manhole smell gurgling roots grease basin sink bath shower verstop afvoer drein stinks smell gurgle',sum:'Slow or blocked basin, sink, shower, gully or main drain',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is blocked?',opts:[['One fixture (basin, sink, shower or bath)','r_one'],['Several fixtures, or a gully overflowing','q_main'],['Gurgling noises or smells, but still draining','r_vent'],['The toilet (WC)','r_wc']]},
  q_main:{q:'Open the nearest rodding eye or inspection chamber (slowly, face away). Is it full of water?',opts:[['Full of water: blockage is downstream','r_down'],['Empty or dry: blockage is upstream','r_up']]},
  r_one:{res:1,cause:'Blocked trap or branch (hair, soap, grease)',do:['Put a bucket under. Unscrew the trap and clean it.','Rod or plunge the branch pipe.','Remake the trap with sound seals.'],parts:[['Basin trap','basin trap'],['Bottle trap','bottle trap']],next:'repair'},
  r_up:{res:1,cause:'Blockage between the last full point and this chamber',do:['Rod from this chamber back up the line.','Flush with water and check the line runs clear.'],parts:[['Drain rods','drain rod']],next:'repair'},
  r_down:{res:1,cause:'Blockage downstream of this chamber (main drain or connection)',do:['Rod or jet from this chamber toward the municipal connection.','If it keeps blocking, use a drain camera: roots, a collapse or a belly in the pipe.','Do not enter manholes (gas).'],parts:[['Drain rods','drain rod']],next:'repair'},
  r_vent:{res:1,cause:'Partial blockage, or a blocked or missing vent, or a trap that is too far from a vent',do:['Clear the drain.','Check the vent pipe is open and not blocked.','Check trap distance to the vent and the pipe size.'],parts:[['Air admittance valve','air admittance valve']],next:'repair'},
  r_wc:{res:1,cause:'Blocked toilet',do:['Use the Blocked toilet scenario.'],next:'repair'}
 }},
 repair:{warn:['Never enter a manhole or sewer chamber (gas). Do not mix drain-cleaning chemicals.'],tools:['Gloves and glasses','Bucket and rags','Drain rods','Plunger','Drain machine (if available)','Torch','Disinfectant'],parts:[['Basin trap','basin trap'],['Bottle trap','bottle trap'],['Drain rods','drain rod'],['Gully trap','gully']],
  steps:['Ask which fixtures are blocked. One fixture means a trap or branch. Several means the main drain.','Wear waterproof gloves and glasses. Protect the floor.','Basin or sink: bucket under, unscrew the trap and clean it. Reassemble with sound seals.','Gully or main drain: lift the grid and remove silt and rubbish. Open the nearest rodding eye slowly, face away.','Find where the water stops: flow before the blockage, dry after.','Rod or machine from the open point toward the blockage. Work gently and do not force rods in a bend.','Flush with plenty of water to check the line is free.','If it blocks again, or the pipe is cracked, collapsed or full of roots: camera inspection and a quote for repair.','Disinfect the area and tools. Photograph the cause. Advise the customer (no grease or wipes down the drain).'],
  sans:['SANS 10252-2 covers drainage: access (rodding eyes) where pipes can be cleared, traps with water seals, falls (minimum 1:46 for waste branches and 1:40 for soil branches) and venting.']}},
{id:'blocked-toilet',title:'Blocked toilet',cat:'toilets,drainage',kw:'blocked toilet wc plunger auger closet pan overflow flush toilet verstop wont flush will not flush clogged',sum:'Toilet will not flush away or is overflowing',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Is the water rising and about to overflow?',opts:[['Yes, close to overflowing','r_stop'],['No, level is stable and drains slowly','q2']]},
  q2:{q:'Do other fixtures (basin, shower, other toilets) drain slowly or gurgle?',opts:[['Yes, others too','r_main'],['No, only this toilet','r_pan']]},
  r_stop:{res:1,cause:'Blockage in the pan or trap. Stop more water going in first',do:['Close the angle valve behind the toilet. Lift the float if you must to stop the cistern filling.','Do not flush again.','Protect the floor. Then clear it (see Repair).'],next:'repair'},
  r_pan:{res:1,cause:'Blockage in the pan trap or just beyond it',do:['Use a flange plunger first.','Then a closet auger if the plunger does not clear it.','Do not use harsh chemicals.'],next:'repair'},
  r_main:{res:1,cause:'Blockage in the branch or main drain, not only the toilet',do:['Open the nearest rodding eye or inspection chamber (face away).','Rod or jet the line.','Use the Blocked drain scenario.'],next:'repair'}
 }},
 repair:{warn:['Wear waterproof gloves and glasses. Do not mix drain-cleaning chemicals. Never enter a manhole.'],tools:['Gloves and glasses','Flange plunger','Closet auger','Old towels and bucket','Disinfectant'],parts:[['WC connector','wc connector'],['Cistern washer','cistern washer']],
  steps:['Close the angle valve behind the toilet. Put towels and a plastic sheet down.','Fit the plunger so it seals in the bowl outlet. Push gently first (air), then pump 10 to 15 times.','If it does not clear, use the closet auger: feed it in, turn the handle and push until it breaks the blockage.','Flush with a bucket of water first. Then flush normally and watch the level.','If it keeps blocking, look for a toy, wipes or a cracked pipe. Lift the pan if needed and inspect the outlet.','If several fixtures are affected, rod the main drain from a rodding eye.','Disinfect the floor, tools and your gloves. Advise the customer: no wipes, nappies or sanitary products in the toilet.'],
  sans:['SANS 10252-2: the pan trap must hold its water seal and the soil pipe must have enough fall (minimum 1:40 for soil branches) and venting.'],see:['blocked-drain','diagnose','Several fixtures blocked? Open "Blocked drain or gully"']}},
{id:'burst-pipe',title:'Burst pipe emergency',cat:'emergency,leaks',kw:'burst pipe emergency flood water off main valve isolate damage leak ceiling pyp bars gebars flood water everywhere',sum:'Water everywhere: stop it first',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Is water flowing now and causing damage?',opts:[['Yes, flooding','r_stop'],['No, it has stopped or is a slow leak','q_where']]},
  q_where:{q:'Can you see where the water comes from?',opts:[['Yes, a visible pipe or joint','r_vis'],['No, inside a wall, ceiling or floor','r_hidden'],['Near the geyser','r_geyser']]},
  r_stop:{res:1,cause:'Stop the water first',do:['Close the main isolating valve (at the meter or house inlet).','Open the lowest tap to drain the system. Open the highest tap to let air in.','If water is near electrics, switch off the main breaker only if it is safe to reach. Otherwise keep away and call an electrician.','If it is the geyser, also close the geyser cold-feed valve and switch off the geyser at the DB.','Take photos of the damage for the insurance.'],next:'repair'},
  r_vis:{res:1,cause:'Failed pipe, joint or fitting',do:['Isolate the section.','Cut out the damaged piece and repair with the correct fitting for the pipe type.','Pressure test.'],next:'repair'},
  r_hidden:{res:1,cause:'Hidden leak',do:['Do a meter test with all taps closed.','Isolate sections to find the leaking branch.','Open the wall or ceiling as little as possible.'],next:'repair'},
  r_geyser:{res:1,cause:'Geyser, valve or pipe leak',do:['Switch off the geyser at the DB. Close the cold-feed valve.','Find the leak: cylinder, safety valve drain, joint or element flange.','A leaking cylinder means the geyser must be replaced.'],next:'repair'}
 }},
 repair:{warn:['Water and electricity: if the DB or sockets are wet, do not touch them. Keep people away and call an electrician.'],tools:['Main isolating key / spanner','Bucket and towels','Wet vacuum','Pipe cutter','Repair couplings','Torch'],parts:[['Repair coupling','repair coupling'],['Copper coupling 22mm','copper coupling 22mm'],['Isolating valve','ball valve'],['Multilayer pipe fittings','multilayer']],
  steps:['Close the main isolating valve. Open the lowest tap to drain, the highest to let air in.','Make electrics safe: switch off the geyser; stay away from a wet DB.','Move people, pets and valuables away. Mop up and ventilate.','Photograph the damage and the burst pipe before you move it.','Cut out the damaged section back to sound pipe.','Fit the correct repair fitting for the pipe type (compression, push-fit, soldered). No tape-and-hope.','Support the pipe properly with clips.','Refill slowly, bleed air and pressure test for at least 15 minutes.','Check the meter with all taps closed: no movement.','Tell the customer what is covered by insurance, what dries out and who does making good.'],
  sans:['SANS 10252-1: pipes must be supported and joined with fittings suited to the pipe material, and tested before being covered.']}},
{id:'geyser-dripping',title:'Geyser dripping / PRV weeping',cat:'geysers',kw:'geyser dripping safety valve prv weeping t&p drain pipe pressure expansion vacuum breaker tray overflow geiser drup overflow pipe dripping outside',sum:'Water from the safety valve drain or the drip tray',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Where is the water coming from?',opts:[['The safety valve drain pipe (outside)','q_amt'],['The drip tray under the geyser','q_tray'],['The vacuum breaker','r_vb'],['A pipe joint on or near the geyser','r_joint']]},
  q_amt:{q:'How much water comes out?',opts:[['A few drips, mostly while the geyser heats','r_exp'],['A steady drip or a stream all the time','q_press']]},
  q_press:{q:'Measure supply pressure with a gauge. Is it above the geyser rating (typically 200, 300 or 400 kPa)?',opts:[['Yes, pressure is too high','r_press'],['No, pressure is within the rating','q_hot']]},
  q_hot:{q:'Is the water at the taps scalding hot, or is the geyser hotter than normal?',opts:[['Yes, scalding or very hot','r_hot'],['No, normal','r_valve']]},
  q_tray:{q:'Is the water coming from the geyser body or from the pipes above the tray?',opts:[['From the geyser body (rust, weeping)','r_cyl'],['From a pipe or valve above the tray','r_joint']]},
  r_exp:{res:1,cause:'Thermal expansion in a closed (non-return valve) system',do:['A small drip while heating is common in a closed system.','If it is more than a small drip, check the pressure and the expansion arrangement the maker requires.','Do not block the drain pipe.'],next:'repair'},
  r_press:{res:1,cause:'Supply pressure too high for the geyser',do:['Fit a pressure control valve set below the geyser rating.','Check the PCV setting if one is already fitted.','Check the pressure again.'],parts:[['Pressure control valve','pressure control valve']],next:'repair'},
  r_hot:{res:1,cause:'Geyser overheating: thermostat or controller fault',do:['Switch the geyser off at the DB. This is urgent: scald and pressure risk.','Electrician checks the thermostat and cut-out.','Check the safety valve works (lift the lever briefly).'],call:'electrician',parts:[['Thermostat','geyser thermostat']],next:'repair'},
  r_valve:{res:1,cause:'Faulty or dirty T&P safety valve',do:['Lift the lever briefly to flush the seat. Let it snap closed.','If it still drips, replace the valve with one of the right pressure rating.'],parts:[['Safety valve','safety valve']],next:'repair'},
  r_vb:{res:1,cause:'Vacuum breaker leaking or faulty',do:['Check the seat for dirt. Replace the vacuum breaker if it keeps leaking.','Check supply pressure is not too high.'],parts:[['Vacuum breaker','vacuum breaker']],next:'repair'},
  r_joint:{res:1,cause:'A joint, valve or pipe leaking',do:['Isolate and dry the area. Watch to find the wet joint.','Remake the joint with new seals or replace the fitting.'],parts:[['Geyser connector','geyser connector']],next:'repair'},
  r_cyl:{res:1,cause:'Corroded cylinder',do:['Isolate the water and the power.','The geyser is finished. Quote a replacement.','Put a bucket and tray to limit damage.'],parts:[['Geyser','geyser 150l']],next:'install'}
 }},
 repair:{warn:[ELEC_WARN],tools:['Pressure gauge','Spanners','PTFE tape','Torch','Hose and bucket'],parts:[['Pressure control valve','pressure control valve'],['Safety (T&P) valve','safety valve'],['Vacuum breaker','vacuum breaker'],['Drip tray','geyser tray']],
  steps:['Measure the supply pressure with a gauge at an outside tap. Write it down and compare with the geyser rating.','Check what is dripping: safety valve drain, vacuum breaker, a joint or the tray.','Lift the safety valve lever briefly. Water must flow and then stop. Never block the drain.','If the pressure is high: fit or reset a pressure control valve to below the geyser rating.','If the valve is faulty: isolate the water, drain down, replace the T&P valve with the same pressure rating and thread.','Check the safety valve drain pipe: metal, continuous fall, no more than 3 bends, no valves or plugs.','Check the drip tray drain and fix the cause of any water in it.','Check again after a day. Tell the customer what was wrong.'],
  sans:['SANS 10254: safety valve drain pipe is metal, at least the size of the valve outlet, with a continuous fall, no more than 3 bends, and discharges where it can be seen. No valve, cap or plug in the drain.','Fit a drip tray with its own drain pipe where a leak can cause damage.']},
 install:{see:['geyser-install','install','Open "Geyser installation / replacement"'],steps:['A corroded cylinder cannot be repaired: quote a new geyser.','Follow the Geyser installation scenario for the valves, tray and safety drain.'],sans:['A new geyser needs a plumbing CoC from a licensed plumber and an Electrical CoC from an electrician where required.']}},
{id:'noisy-pipes',title:'Noisy pipes / water hammer',cat:'pressure',kw:'noisy pipes water hammer banging clicking whistle vibrating rattle arrester hammer hammering banging knocking thumping rattling pipes noise lawaai',sum:'Bang, click, whistle or rattle in the pipes',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What sort of noise is it?',opts:[['A bang when a tap or valve closes','r_ham'],['Clicking or ticking when the geyser heats','r_click'],['Whistling or squealing','r_whistle'],['Rattle or vibration','r_rattle'],['Banging when the cistern fills','r_fill'],['Noise from the pump','r_pump']]},
  r_ham:{res:1,cause:'Water hammer: high pressure, fast-closing valves or loose pipes',do:['Measure supply pressure. Fit or set a pressure control valve if it is high.','Clip loose pipes.','Fit a water hammer arrester near the noisy valve or appliance.'],parts:[['Water hammer arrester','water hammer arrester'],['Pressure control valve','pressure control valve']],next:'repair'},
  r_click:{res:1,cause:'Pipes expanding and rubbing in clips or sleeves',do:['Loosen or pad the clips. Add sleeves where pipes pass through walls.'],parts:[['Pipe clips','pipe clip'],['Pipe lagging','lagging']],next:'repair'},
  r_whistle:{res:1,cause:'A partly closed valve, worn washer or cartridge, or high flow',do:['Open valves fully.','Replace worn washers or cartridges.','Check the pressure.'],parts:[['Cartridge','cartridge'],['Tap washer','tap washer']],next:'repair'},
  r_rattle:{res:1,cause:'Pipes touching walls or each other',do:['Add clips and pads.','Support long runs.'],parts:[['Pipe clips','pipe clip']],next:'repair'},
  r_fill:{res:1,cause:'Faulty or worn cistern fill valve',do:['Replace the fill valve.'],parts:[['Fill valve','fill valve']]},
  r_pump:{res:1,cause:'Air in the pump or poor mountings',do:['Bleed the air.','Check the mounting pads and the pipe connections.','Check the pump pressure settings.'],parts:[['Pump','pump']]}
 }},
 repair:{tools:['Pressure gauge','Pipe clips and screws','Pipe insulation','Spanners','Hacksaw or pipe cutter'],parts:[['Water hammer arrester','water hammer arrester'],['Pressure control valve','pressure control valve'],['Pipe clips','pipe clip'],['Pipe lagging','lagging']],
  steps:['Find where the noise starts: open and close the taps one at a time.','Measure the supply pressure. High pressure makes water hammer worse.','Clip every loose pipe. Add pads where pipes touch.','Fit a water hammer arrester close to the quick-closing valve or machine.','Replace worn washers and cartridges that whistle.','Check again with all taps and appliances. Note what was done.'],
  sans:['SANS 10252-1 covers pipe support and pressure in water installations. Check the maker\u2019s data for pressure control valve settings.']}},
{id:'hot-too-hot-cold',title:'Hot water too hot or too cold',cat:'geysers',kw:'hot water too hot scald cold temperature thermostat mixing valve 60 legionella warm koud scalding burning',sum:'Scalding hot, or never really hot',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is the problem?',opts:[['Water is scalding hot at the taps','q_hot'],['Water is only warm or lukewarm','q_warm']]},
  q_hot:{q:'Is the safety valve dripping or is the geyser making steam or boiling noises?',opts:[['Yes','r_danger'],['No, just very hot at the tap','r_set']]},
  q_warm:{q:'Is the thermostat set to about 60 \u00B0C and is the geyser big enough?',opts:[['Setting is low','r_low'],['Setting is right, geyser is big enough','r_elem'],['Not sure','r_elem']]},
  r_danger:{res:1,cause:'Geyser overheating: thermostat or cut-out fault. This is dangerous (scalding and pressure)',do:['Switch the geyser OFF at the DB now.','Do not draw very hot water for the children. Warn the customer.','Check the safety valve is working and the drain is clear.','Electrician checks the thermostat and cut-out.'],call:'electrician',next:'repair'},
  r_set:{res:1,cause:'Thermostat is set too high, or there is no mixing protection',do:['Electrician sets the thermostat to about 60 \u00B0C.','Fit a thermostatic mixing valve at showers and baths for children and the elderly.','Warn the customer about scalding.'],call:'electrician',parts:[['Thermostatic mixing valve','thermostatic mixing valve']],next:'repair'},
  r_low:{res:1,cause:'Thermostat or controller set too low',do:['Electrician sets the thermostat to about 60 \u00B0C.','Do not keep the tank below about 60 \u00B0C: bacteria (legionella) can grow.'],call:'electrician'},
  r_elem:{res:1,cause:'Failing element or thermostat, or a small geyser',do:['Follow the Geyser not heating scenario.'],call:'electrician',next:'repair'}
 }},
 repair:{warn:['A geyser that boils or is much too hot can scald and can burst. Switch it off at the DB and call an electrician.',ELEC_WARN],tools:['Thermometer','Torch','Spanners'],parts:[['Thermostatic mixing valve','thermostatic mixing valve'],['Geyser thermostat','geyser thermostat'],['Safety valve','safety valve']],
  steps:['Measure the water temperature at the tap with a thermometer after it runs for a minute.','Geysers are usually set to about 60 \u00B0C. Above that, scalding risk goes up. Below about 60 \u00B0C, bacteria risk goes up.','Electrician checks and sets the thermostat. A faulty thermostat is replaced.','Fit a thermostatic mixing valve for showers and baths where scald risk is a worry.','Check the safety valve works and its drain is clear.','Tell the customer the safe temperature and what you changed.'],
  sans:['SANS 10254 covers fixed electric storage water heaters including safety devices. Check the current standard for the temperature limits where children or elderly people use the water.']}},
{id:'pump-not-starting',title:'Pump not starting',cat:'pressure',kw:'pump not starting booster pump jockey tank pressure switch dry run prime breaker pomp booster pump borehole pump wont start',sum:'Booster or tank pump will not run, or runs and gives no water',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What does the pump do?',opts:[['Nothing (no sound, no light)','q_pow'],['Hums but does not turn','r_stuck'],['Runs but delivers no water or very little','q_prime'],['Starts and stops again and again','r_cycle']]},
  q_pow:{q:'Is there power at the plug or DB, and is the pump breaker on?',opts:[['No power / breaker tripped','r_power'],['Power is on','r_switch']]},
  q_prime:{q:'Is the tank or water source empty, or is there air in the suction pipe?',opts:[['Tank empty','r_dry'],['Source has water','r_prime']]},
  r_power:{res:1,cause:'No power to the pump',do:['Check the plug, extension lead, breaker and earth leakage.','Reset a tripped breaker once only. If it trips again call an electrician.'],call:'electrician'},
  r_switch:{res:1,cause:'Pressure switch or controller fault',do:['Check the pressure switch settings and contacts.','Check the controller error lights.','Electrician checks the pump motor and capacitor.'],call:'electrician',parts:[['Water pumps','water pump']],next:'repair'},
  r_stuck:{res:1,cause:'Seized impeller or a failed capacitor',do:['Switch off at the DB. Check the pump turns by hand at the fan end (if designed so).','Electrician checks the capacitor and motor.'],call:'electrician',next:'repair'},
  r_dry:{res:1,cause:'Dry running. Stop the pump to protect the seal',do:['Switch the pump off.','Fix the water supply to the tank.','Prime the pump before restarting.'],next:'repair'},
  r_prime:{res:1,cause:'Pump lost its prime or air is in the suction pipe',do:['Switch off. Fill the pump body through the priming plug.','Check the suction pipe joints are airtight and the foot valve seals.','Restart and check flow.'],parts:[['Non-return valve','non return valve']],next:'repair'},
  r_cycle:{res:1,cause:'Short cycling: waterlogged pressure vessel, leak, or a faulty non-return valve',do:['Check the pressure vessel air charge.','Check for leaks in the pipes and at the taps.','Check the non-return valve.'],parts:[['Pressure gauge','pressure gauge'],['Non-return valve','non return valve']],next:'repair'}
 }},
 repair:{warn:['Pump wiring and motor repairs: registered electrician only.'],tools:['Spanners','PTFE tape','Pressure gauge','Torch','Bucket'],parts:[['Water pumps','water pump'],['Non-return valve','non return valve'],['Pressure gauge','pressure gauge']],
  steps:['Switch the pump off at the plug or DB.','Check there is water at the source. Never run a pump dry.','Check the power: plug, lead, breaker and earth leakage.','Prime the pump: fill the body through the priming plug and check the suction pipe is airtight.','Check the pressure switch settings and the vessel air charge.','Check the non-return valve and the foot valve.','Restart. Watch the pressure and the cycle for a few minutes. Note what was done.'],
  sans:['SANS 10252-1: a pump supplying a building must not allow back-flow into the municipal main. Check the correct backflow protection.']}},
{id:'meter-running',title:'Water meter running with taps off',cat:'leaks',kw:'water meter running leak hidden leak bill high toilet geyser irrigation meter test pressure drop meter loop lekkasie leak detection high water bill',sum:'Find a hidden leak with the meter test',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Close every tap and appliance. Is the meter dial (or the small low-flow indicator) moving?',opts:[['Yes, it is moving','q2'],['No, it is still','r_none']]},
  q2:{q:'Close the main valve at the house. Does the meter still move?',opts:[['Yes, still moving','r_meter'],['It stops, so the leak is in the house or garden','q3']]},
  q3:{q:'Close the geyser cold-feed valve. Does the meter stop?',opts:[['Yes, it stops','r_geyser'],['No, still moving','q4']]},
  q4:{q:'Close the garden / irrigation line. Does it stop?',opts:[['Yes','r_garden'],['No','q5']]},
  q5:{q:'Add food colouring to each cistern. Is there colour in a bowl after 10 minutes?',opts:[['Yes','r_wc'],['No','r_hidden']]},
  r_none:{res:1,cause:'No leak at the moment',do:['Check again at a quiet time (the leak may be intermittent).','Check the bill: an estimated reading or a change in use can explain it.'],call:'municipality'},
  r_meter:{res:1,cause:'The meter itself or the pipe before the house valve',do:['Check the meter and the pipe between the meter and the valve for a leak.','Report a faulty meter to the municipality.'],call:'municipality'},
  r_geyser:{res:1,cause:'Leak on the hot side: geyser, safety valve or hot pipes',do:['Check the safety valve drain, the drip tray, the roof space and the hot pipes.','Look for wet ceilings and warm floors.'],next:'repair'},
  r_garden:{res:1,cause:'Leak in the garden or irrigation',do:['Check taps, hoses and irrigation valves.','Look for wet patches and trace the line.'],next:'repair'},
  r_wc:{res:1,cause:'A toilet is leaking into the bowl',do:['Replace the flush valve seal or the fill valve.'],parts:[['Flush valve','flush valve'],['Fill valve','fill valve']],next:'repair'},
  r_hidden:{res:1,cause:'Hidden leak in the cold supply pipes (slab, wall or underground)',do:['Isolate sections to narrow it down.','Pressure test the isolated section.','Use a listening device or a leak detection service.','Open up as little as possible.'],next:'repair'}
 }},
 repair:{tools:['Pressure gauge','Isolating key','Food colouring','Torch','Listening device (if available)','Camera'],parts:[['Pressure gauge','pressure gauge'],['Repair coupling','repair coupling'],['Isolating valve','ball valve']],
  steps:['Ask: where and when did the leak start? Any change in the bill? Any sound of running water?','Close every tap and appliance. Read the meter and note the digits and the low-flow indicator.','Close the main valve at the house. If the meter still moves, the leak is before the house valve.','Isolate sections one at a time (geyser, garden, house) and watch the meter.','Check the usual suspects: toilets (food colouring test), dripping taps, geyser safety-valve drain, outside taps and irrigation.','Pressure test the leaking section with a gauge and look for a drop.','Pinpoint: look for damp, stains, warm floor patches (hot pipe); listen; use a moisture meter or thermal camera.','Open up as little as possible. Take photos. Repair, pressure test for at least 15 minutes and re-check the meter.'],
  sans:['SANS 10252-1: new or repaired water pipes should be tested under pressure before being covered.']}},
{id:'geyser-install',title:'Geyser installation / replacement',cat:'geysers,install',kw:'geyser installation replace new install drip tray safety valve t&p vacuum breaker pressure control valve certificate coc insulation base geiser installeer new geyser replace geyser',sum:'Replace an electric geyser (indoor roof or outside)',
 install:{warn:[ELEC_WARN,'Working in the roof space: step only on trusses or a board, with a head torch, and tell someone you are up there. Two people to lift the geyser.'],
  tools:['Two people to lift','Ladder, torch / head-lamp','Spanners and adjustable spanners','Pipe cutter, hacksaw','Pressure gauge','Hose and bucket','PTFE tape and new connectors','Spirit level','Camera for photos'],
  parts:[['Geyser','geyser 150l'],['Safety (T&P) valve','safety valve'],['Vacuum breaker','vacuum breaker'],['Pressure control valve','pressure control valve'],['Non-return valve','non return valve'],['Isolating valve','ball valve 22mm'],['Drip tray','geyser tray'],['Geyser connectors','geyser connector'],['Pipe lagging','lagging'],['Copper pipe 22mm','copper pipe 22mm'],['22mm elbow','22mm elbow']],
  steps:['Check the old geyser: size (litres), pressure rating (kPa) and type. Photograph the data plate. Check supply pressure with a gauge.','Switch off the geyser breaker at the DB and the isolator. Label it. Test it is dead (electrician).','Close the cold feed isolating valve. Open a hot tap in the house to relieve pressure.','Drain the geyser through the drain cock or a hose to a safe place. The water may be scalding: let it cool or draw hot water off first.','Disconnect the pipes and the safety valve drain. The electrician disconnects the wiring. Lift the geyser out with two people.','Check the drip tray and its drain pipe. It must be bigger than the geyser, level, and drain with a fall to a visible, safe outside point. Replace it if rusty or cracked.','Set the new geyser on a solid base or secure brackets that carry the full weight (a full 150 L geyser weighs about 170 kg).','Fit the valves in the order the maker shows: isolating valve, non-return valve, pressure control valve if supply pressure is above the geyser rating, vacuum breaker(s) above the top of the geyser, and the T&P safety valve on the geyser safety port.','Connect the safety valve drain: metal, at least the valve size, continuous fall, no more than 3 bends, discharging to a visible place outside. No valve or cap in it.','Connect cold in and hot out to the correct ports with new connectors. Insulate the hot pipe and the geyser as required.','Fill slowly with a hot tap open until water runs without air. Close the tap. Check every joint for leaks.','Only when the geyser is full: the electrician reconnects and switches on (Electrical CoC). Set the thermostat (usually about 60 \u00B0C).','Check the safety valve drain for drips. Briefly lift the valve lever: water must flow and then stop.','Take photos. Complete the plumbing Certificate of Compliance if required (licensed plumber).','Hand over: show the customer the isolating valve and the DB switch.'],
  sans:['SANS 10254 covers the installation of fixed electric storage water heaters. Follow it and the geyser maker\u2019s instructions.','Safety valve drain: metal, at least the valve outlet size, continuous fall (no upward sections), no more than 3 bends, discharging where it can be seen outside, and no valve, cap or plug in it.','Fit a drip tray with its own drain where a leak can cause damage.','A plumbing CoC can only be issued by a licensed (PIRB) plumber. Insurers often ask for it when a geyser is replaced. The Electrical CoC is the electrician\u2019s.']}},
{id:'basin-mixer-replace',title:'Basin / mixer replacement',cat:'taps,install',kw:'basin mixer replace tap pedestal angle valves flexi trap waste install tile wall bracket wasbak mengkraan new tap pedestal basin',sum:'Replace a pedestal basin, mixer, angle valves, flexis, waste and trap',
 install:{warn:['Tiled walls and floors: use the right masonry bit and go slowly (no hammer action on tile). Basins are heavy: fix to a solid wall or board, not to drywall alone.'],
  tools:['Basin spanner','Adjustable spanners','Drill and tile / masonry bits','Spirit level','Tape measure','Screwdrivers','Silicone gun','Bucket and towels','PTFE tape'],
  parts:[['Basin','basin'],['Pedestal','pedestal'],['Basin mixer','basin mixer'],['Angle valves','angle valve'],['Flexi hoses','flexi'],['Basin waste','basin waste'],['Trap','basin trap'],['Fixing bolts','basin fixing'],['Silicone','silicone'],['PTFE tape','ptfe tape']],
  steps:['Close the water (angle valves or room valve). Open the old tap to release pressure.','Put a bucket and towels down. Disconnect the flexi hoses, the trap and the waste. Remove the old basin and pedestal.','Check the wall and floor: solid fixing needed. Mark the position (rim about 800 to 850 mm above the floor), check level and where the waste outlet comes out of the wall or floor.','Fit the tap and the waste to the basin before mounting it. Fit new angle valves on the supply pipes (PTFE on threads).','Mount the basin level: drill the wall fixings (tile bit first, then masonry bit), use correct plugs and bolts. Set the pedestal on the floor and fix it. Do not over-tighten (porcelain cracks).','Connect new flexi hoses to the mixer and angle valves: hot on the left, cold on the right. Do not kink them.','Connect the trap and the waste pipe with a fall to the waste outlet.','Flush the supply lines into a bucket before connecting the hoses to the tap (debris damages the cartridge).','Open the angle valves slowly. Check every joint for leaks, wipe dry and check again after 10 minutes.','Fill the basin and let it run out: check the trap and waste joints. Seal the basin to the wall with silicone. Clean and remove protective plastic.','Show the customer the angle valves.'],
  sans:['SANS 10252-1: an isolating (angle) valve at each fixture is good practice. Use new flexi hoses.','SANS 10252-2: trap fitted and holds its water seal; waste falls at least 1:46 (waste branch); trap outlet not more than 6 m of pipe from a vent.','Check the tap suits the pressure system (low-pressure taps for gravity-fed geysers).']},
 repair:{tools:['Basin spanner','Adjustable spanner','Screwdrivers','Bucket and towel','PTFE tape'],parts:[['Basin mixer','basin mixer'],['Cartridge','mixer cartridge'],['Flexi hoses','flexi'],['Angle valves','angle valve']],
  steps:['Close the angle valves. Open the tap to release pressure.','Disconnect the flexi hoses. Undo the fixing nut with a basin spanner and lift out the old mixer.','Clean the surface. Check the new mixer suits the hole size and the pressure system.','Fit the new mixer with its washers. Do not over-tighten the fixing nut (ceramic can crack).','Fit new flexi hoses. Flush the lines into a bucket first. Connect and open the valves slowly.','Test hot and cold, check every joint dry after 10 minutes.'],
  sans:['SANS 10252-1: isolating valve at each fixture; use new flexi hoses.'],see:['basin-mixer-replace','install','Full basin replacement steps are on the Install tab']}},
{id:'toilet-pan-replace',title:'Toilet pan replacement',cat:'toilets,install',kw:'toilet pan wc replace install cistern connector p-trap s-trap close coupled floor fixing flush angle valve flexi toilet vervang new toilet wc',sum:'Replace a toilet pan and cistern',
 install:{warn:['Porcelain cracks if over-tightened. Wear waterproof gloves and glasses. Lift with care: pans and cisterns are heavy.'],
  tools:['Adjustable spanners','Screwdrivers','Drill and bits for the floor','Spirit level','Silicone gun','Bucket, sponge and towels','Gloves and glasses'],
  parts:[['WC pan','toilet pan'],['Close-coupled cistern','cistern'],['WC connector','wc connector'],['Fill valve','fill valve'],['Flush valve','flush valve'],['Angle valve','angle valve'],['Flexi hose','flexi'],['Pan fixing kit','pan fixing'],['Silicone','silicone']],
  steps:['Close the angle valve. Flush to empty the cistern and sponge out the rest. Disconnect the flexi hose.','Unscrew the cistern bolts and lift the cistern off. Unscrew the pan from the floor and break the seal at the outlet. Lift the pan away. Block the open pipe with a rag (sewer gas).','Check the outlet type: P-trap (to the wall) or S-trap (to the floor) and the distance from the wall to the centre of the outlet. The new pan must match.','Check the floor is flat and the soil pipe end is clean and undamaged.','Fit the WC connector or push-fit soil connection to the 110 mm drain. Clean the pipe end and lubricate the seal.','Set the pan, mark and drill the floor fixings. Use plugs suited to the floor. Fix with the correct bolts and washers. Do not over-tighten.','Fit the cistern (close-coupled: seal and bolts; wall-hung: bracket and flush pipe).','Fit a new angle valve and flexi hose to the cistern inlet.','Open the angle valve. Flush several times. Check the water level, fill valve cut-off, flush volume and every joint for leaks.','Check the pan outlet seal and trap: no leaks and the trap holds water in the bowl.','Seal around the base with sanitary silicone if the customer wants it. Clean and show the customer the angle valve.'],
  sans:['SANS 10252-2: the pan trap holds its water seal; soil pipe falls at least 1:40 (soil branch) with no flat or backward sections; the trap outlet is not more than 6 m of pipe from a ventilated stack or drain.','SANS 10252-1: an isolating (angle) valve at the cistern, and an overflow that discharges safely.']}},
{id:'geyser-element-thermostat',cat:'geysers',title:'Geyser element or thermostat replacement',kw:'geyser element thermostat replace change burnt element tripping reset button thermal cut-out flange gasket hard water geiser element vervang termostaat',sym:'geyser has water but stays cold; element burnt out; thermostat not switching; reset button keeps popping; geyser tripping the DB',sum:'Swap a failed element or thermostat (electrician) with the plumber draining and refilling',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is the geyser doing?',opts:[['No heat at all, breaker stays on','q2'],['Breaker trips (straight away or after a while)','r_trip'],['Heats but water is too hot or boils','r_hot'],['Heats, but runs out fast','r_size']]},
  q2:{q:'Is the geyser full of water and is there power at the geyser (electrician check)?',opts:[['Full, power is present','r_el'],['Not full, valve closed, or leaking','r_empty'],['No power at the geyser','r_nopow']]},
  r_trip:{res:1,cause:'Earth fault: failed element (most common), wet wiring or a faulty thermostat',why:'An element that leaks current to the tank body trips the earth-leakage switch. Do not keep resetting it.',do:['Leave the geyser breaker OFF and label it.','Electrician tests the element and thermostat insulation to earth.','Plumber: look for water on the electrics, or a leaking flange or safety valve drain wetting the cover.'],call:'electrician',parts:[['Element','geyser element'],['Thermostat','geyser thermostat'],['Gasket','geyser gasket']],next:'repair'},
  r_hot:{res:1,cause:'Thermostat stuck on or set too high; the thermal cut-out and the safety valve are the last defences',do:['Switch the geyser OFF at the DB and stop using very hot water.','Electrician replaces the thermostat and checks the cut-out.','Plumber checks the safety (T&P) valve and its drain pipe for discharge.','Fit a mixing valve at the geyser outlet if scald risk is a concern.'],call:'electrician',parts:[['Thermostat','geyser thermostat'],['Safety valve','safety valve']],next:'repair'},
  r_size:{res:1,cause:'A broken top element (a geyser with two elements), scale on the element, or the tank is too small',do:['Electrician tests each element.','Drain and look for scale and sludge.','Replace the failed element with one made for hard water if the water is hard.','If the demand is simply too big, quote a bigger geyser or a second one.'],call:'electrician',parts:[['Element','geyser element'],['Anode','anode']],next:'repair'},
  r_el:{res:1,cause:'Failed element or tripped thermal cut-out',do:['Electrician tests the element (it should read a resistance, not open circuit) and the thermostat.','If the cut-out has tripped, find out why before pressing reset.','Replace the failed parts with the same rating and flange type.'],call:'electrician',parts:[['Element','geyser element'],['Thermostat','geyser thermostat'],['Gasket','geyser gasket']],next:'repair'},
  r_empty:{res:1,cause:'Dry or isolated geyser. A dry element burns out within minutes',do:['Switch the geyser OFF at the DB.','Open the cold feed isolating valve and a hot tap until water flows without air.','Look for leaks at the tank, flange and valves.','Only switch on when full.'],parts:[['Isolating valve','ball valve 22mm']],next:'repair'},
  r_nopow:{res:1,cause:'Electrical supply problem (breaker, isolator, wiring, timer)',do:['Check the DB breaker and any isolator once only.','Check a timer or controller.','Electrician traces the supply.'],call:'electrician'}}},
 repair:{warn:[ELEC_WARN,HOT_WARN],tools:['Electrician with tester','Hose and bucket','Socket set / element spanner','New gasket','Torch','Camera for photos'],parts:[['Element','geyser element'],['Thermostat','geyser thermostat'],['Flange gasket','geyser gasket'],['Anode','anode'],['Element tester','geyser element tester']],
  steps:['Switch the geyser OFF at the DB and isolator. Label the breaker "Do not switch on". The electrician proves it is dead.','Note the geyser make, litres, kPa rating and the element rating (kW) and flange type (5 or 6 hole, round or square). Photograph the data plate.','Close the cold feed isolating valve. Open a hot tap in the house to let air in.','Draw off or drain the geyser below the level of the element flange through the drain cock to a safe place. Hot water: let it cool or draw it off first.','Electrician disconnects and labels the wires, then removes the cover and the element or thermostat.','Undo the element flange nuts, remove the old element and clean the flange face. Look inside for scale and sludge; flush it out.','Check the sacrificial anode. Replace it if it is mostly eaten away.','Fit the new gasket and element with the same orientation. Tighten the nuts evenly in a cross pattern, not too hard.','Close the drain cock. Open the cold feed isolating valve and a hot tap and fill until water runs without air. Close the tap.','Check the flange for weeping before any power goes on. Wait a few minutes and look again.','Only when the geyser is full and dry at the flange: the electrician reconnects, fits the cover and switches on. Set the thermostat (about 60 °C).','After an hour check the flange again, the safety valve drain and the hot outlet pipe is warming.','Give the Electrical CoC (electrician) to the customer and keep your photos.'],
  sans:['SANS 10254 covers the installation of fixed electric storage water heaters. Follow it and the maker instructions.','Electrical work on the geyser needs a registered electrical person and an Electrical Certificate of Compliance.','Use the same type and rating of element and thermostat as the geyser maker specifies.']}},

{id:'geyser-tripping-db',cat:'geysers',title:'Geyser tripping the DB',kw:'geyser tripping db trips breaker earth leakage rcd kicks out cuts out power geiser trip skakelaar elcb overload',sym:'geyser trips the breaker; earth leakage trips when geyser comes on; DB trips at night; DB trips after rain',sum:'Breaker or earth leakage trips when the geyser heats',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Which device trips, and when?',hint:'Look at the DB only. Do not open covers.',opts:[['The geyser breaker trips when it switches on or soon after','q2'],['The main earth-leakage (RCD) trips, sometimes only when geyser heats','q2'],['It trips only after rain or when taps run','r_wet'],['Wet DB, burning smell or hot cables','r_danger'],['Nothing trips but the DB feels hot','r_danger']]},
  q2:{q:'Switch the geyser breaker OFF. Does everything else now stay on?',opts:[['Yes, only the geyser circuit causes it','q3'],['No, other circuits also trip','r_other']]},
  q3:{q:'Is there any water leaking on or around the geyser (cover, flange, safety valve drain, tray)?',opts:[['Yes, wet','r_leak'],['Dry','r_elem']]},
  r_danger:{res:1,cause:'Unsafe electrics',do:['Do not touch the DB or wiring.','Switch off at the main only if it is safe to do so.','Keep people away and call a registered electrician now.'],call:'electrician'},
  r_wet:{res:1,cause:'Water getting into the electrics or an outside circuit',do:['Electrician checks the DB, geyser cover, roof leaks and cable entries.','Plumber checks roof pipes, geyser valves and the drip tray for leaks onto the wiring.'],call:'electrician'},
  r_other:{res:1,cause:'Not the geyser: a wiring or appliance fault on the property',do:['Leave the geyser OFF.','Electrician finds the faulty circuit (earth leakage tests one circuit at a time).'],call:'electrician'},
  r_leak:{res:1,cause:'Water on the geyser electrics, from a leaking flange, valve or tank',do:['Leave the breaker OFF.','Find where the water comes from: flange gasket, safety valve drain, vacuum breaker, a seam or the tank body.','Fix or replace what leaks. Dry the cover and wiring; the electrician tests before switching on.'],call:'electrician',parts:[['Flange gasket','geyser gasket'],['Safety valve','safety valve']],next:'repair'},
  r_elem:{res:1,cause:'Element or thermostat leaking current to earth (normal wear, often from scale)',do:['Leave the geyser OFF and label it.','Electrician tests the element and thermostat insulation and replaces what failed.','Plumber drains, replaces and refills as needed (see the element guide).'],call:'electrician',parts:[['Element','geyser element'],['Thermostat','geyser thermostat']],next:'repair'}}},
 repair:{warn:[ELEC_WARN],tools:['Electrician with insulation tester','Torch','Hose and bucket','Camera'],parts:[['Element','geyser element'],['Thermostat','geyser thermostat'],['Flange gasket','geyser gasket']],
  steps:['Leave the geyser breaker OFF and label it with the date. Tell the customer why.','Look at the geyser, valves, tray and drain: any water on or near the electrics? Photograph.','Electrician proves the geyser circuit is dead and removes the cover.','Electrician tests element and thermostat insulation resistance to earth and checks the wiring for damp or burnt cables.','Plumber: if the flange or a valve leaks, isolate and drain as needed and fix it first (see the element guide).','Replace the failed element or thermostat, dry the cover area and reassemble.','Fill the geyser completely before any power goes on.','Electrician switches on and watches that the breaker holds and the geyser starts to heat.','Return after a day to confirm hot water and no trips. Keep photos.'],
  sans:['Earth-leakage protection is required on socket and many other circuits under the wiring code (SANS 10142-1). Never bypass or replace a tripping device with a bigger one.','Electrical work on the geyser: registered electrical person and Electrical CoC.']}},

{id:'geyser-leaking-tank',cat:'geysers',title:'Geyser leaking from the tank',kw:'geyser leaking tank rust corroded burst cylinder water coming out of geyser seam wet ceiling geiser lek tenk replace',sym:'water pouring out of the geyser; rust stains; wet ceiling under geyser; geyser overflow tray full',sum:'Find where the water comes from and decide: repair a fitting or replace the geyser',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Where is the water coming from?',hint:'Isolate the water and power first if it is running heavily.',opts:[['From the flange (element/thermostat plate)','r_flange'],['From a pipe joint or valve','r_joint'],['From the safety valve drain pipe','r_prv'],['From the body or a seam of the tank, or rust-coloured stains','r_tank'],['Not sure','q2']]},
  q2:{q:'Dry the geyser and valves with a cloth and watch for 10 minutes. Where does the water appear first?',opts:[['At a joint, valve or flange','q1'],['Through the outer casing or from the bottom','r_tank'],['Only when the water is heating','r_prv']]},
  r_flange:{res:1,cause:'Perished flange gasket or loose nuts',do:['Switch off power, close the cold feed, drain below the flange.','Replace the gasket; clean the flange face; tighten evenly.','Refill, check dry before power is on.'],call:'electrician',parts:[['Flange gasket','geyser gasket'],['Element','geyser element']],next:'repair'},
  r_joint:{res:1,cause:'Failed connector, valve or pipe joint',do:['Close the cold feed.','Replace the leaking connector or valve (new washers; do not reuse old ones).','Refill, bleed and check dry.'],parts:[['Isolating valve','ball valve 22mm'],['Geyser connector','geyser connector'],['Vacuum breaker','vacuum breaker']],next:'repair'},
  r_prv:{res:1,cause:'Safety valve discharging (see Geyser dripping): pressure, a worn valve or overheating',do:['Check the supply pressure with a gauge and the geyser kPa rating.','Fit a pressure control valve if the pressure is above the geyser rating.','Replace a worn safety valve with the right kPa rating.'],parts:[['Safety valve','safety valve'],['Pressure control valve','pcv']],next:'repair'},
  r_tank:{res:1,cause:'Corroded or split inner tank: the geyser is finished',why:'A leaking cylinder cannot be repaired safely. Anodes only slow corrosion; once water is through the tank, replace the geyser.',do:['Switch the geyser OFF at the DB and close the cold feed.','Drain it to a safe place. Protect the ceiling and floor.','Quote a replacement geyser (see Geyser installation). Check the warranty and the date on the data plate.','If the ceiling is wet, tell the customer: insurance may ask for photos and the plumbing CoC.'],call:'electrician',parts:[['Geyser 150 l','geyser 150l'],['Drip tray','geyser tray']],next:'repair'}}},
 repair:{head:'Stop the leak and make safe',warn:[ELEC_WARN,HOT_WARN],tools:['Hose and bucket','Spanners','Wet vac','Camera','Torch'],parts:[['Geyser 150 l','geyser 150l'],['Geyser 100 l','geyser 100l'],['Drip tray','geyser tray'],['Flange gasket','geyser gasket'],['Geyser connector','geyser connector']],
  steps:['Switch the geyser OFF at the DB (label it) and close the cold feed isolating valve.','Open a hot tap in the house so air can enter, then open the drain cock to a hose that runs to a safe place.','Photograph the leak, the data plate and the damage (insurance).','Find the source: flange, joints, valves, safety valve drain, or the tank itself.','A leaking fitting: replace the fitting or washer and retest. A leaking tank: leave it drained and quote a replacement.','Dry the area. Put the customer\u2019s belongings out of the water and open ceilings only as needed to drain the water.','If the geyser is replaced: follow Geyser installation / replacement. The old geyser comes out with two people.','Fit a drip tray with a drain to a safe visible place.','Refill, bleed air, test all joints, and let the electrician switch on once full.','Explain to the customer what failed and when to expect hot water. Keep your photos.'],
  sans:['SANS 10254: a drip tray with its own drain is the norm where a leak could damage the building.','Geyser replacement can need a plumbing CoC (licensed plumber) and an Electrical CoC.']}},

{id:'geyser-valves-tray',cat:'geysers,compliance',title:'Geyser valves: vacuum breaker, safety valve, PRV and drip tray',kw:'geyser vacuum breaker safety valve prv pressure control valve non return isolating drip tray t&p drain pipe valve order replace geiser kleppe',sym:'geyser valve dripping; which valves does a geyser need; vacuum breaker spitting; drip tray rusted',sum:'What goes where on a pressurised geyser, and how to replace one',
 repair:{warn:[ELEC_WARN,HOT_WARN,'Never cap, plug or valve the safety valve drain. Never replace a safety valve with one of a higher pressure rating than the geyser.'],tools:['Adjustable spanners','Pipe wrenches','PTFE tape','Hose and bucket','Pressure gauge','Tape measure'],parts:[['Vacuum breaker','vacuum breaker'],['Safety (T&P) valve','safety valve'],['Pressure control valve','pcv'],['Non-return valve','non return valve'],['Isolating valve','ball valve 22mm'],['Drip tray','geyser tray'],['Tray outlet adaptor','drip tray']],
  steps:['Read the geyser data plate: working pressure (kPa), litres and port positions. Measure the supply pressure with a gauge on a tap or hose bib.','Isolate: switch off the geyser, close the cold feed, open a hot tap to relieve pressure and drain below the valve you are changing.','Cold feed in the maker order: isolating valve, then non-return valve (if the maker requires one), then a pressure control valve if the supply pressure is above what the geyser can take, then the vacuum breaker, then the geyser.','Vacuum breaker: fit on the pipe above the top of the geyser, in the position the maker shows, vertical, with the cap facing up and free to breathe. It is normal for it to leak a little when it opens; it should not drip all the time.','Safety (T&P) valve: fit on the geyser safety port. The kPa rating on the valve must match the geyser rating.','Safety valve drain: metal pipe, at least the valve outlet size, falling all the way, no more than 3 bends, ending where it can be seen outside. No valve, cap or plug in it.','Pressure control valve: choose one that reduces below the geyser rating (see the maker table). Fit with the arrow in the flow direction, after the isolating valve.','Drip tray: larger than the geyser footprint, level, with a drain pipe falling to a safe visible place. Do not connect the tray drain to the safety valve drain.','Use thread tape or the maker seal; do not over-tighten brass.','Open the isolating valve slowly, open a hot tap to bleed air, then check every joint for leaks.','Raise the safety valve lever briefly: water must run, then stop. Check the valve does not drip once the geyser heats.','Photograph all valves and the drain for the record.'],
  sans:['SANS 10254 / SANS 10252-1: safety valve drain metal, size not less than the valve outlet, continuous fall, no more than 3 bends, discharging where it can be seen.','The vacuum breaker and non-return arrangement protects the supply from backflow and the geyser from being siphoned dry: follow the maker\u2019s layout.','Valve ratings must suit the geyser kPa rating. Check the data plate.'],see:['geyser-dripping','diagnose','If a valve keeps dripping, use the Dripping geyser guide']},
 install:{warn:[ELEC_WARN],tools:['Spanners','Hacksaw / pipe cutter','PTFE tape','Spirit level'],parts:[['Drip tray','geyser tray'],['Vacuum breaker','vacuum breaker'],['Safety valve','safety valve'],['22mm copper pipe','copper pipe 22mm']],
  steps:['Measure the geyser footprint and choose a tray larger than it with room for the drain.','Check the tray is level and supported on a base that takes the geyser weight.','Run the tray drain pipe with a continuous fall to a visible safe outside point (not into a gutter that could be blocked, not into the sewer without an air break).','Fit the safety valve drain separately: metal, correct size, fall, three bends maximum.','Label the isolating valve so the customer can find it.'],
  sans:['A drip tray is required where a leak can cause damage. Check the municipal by-laws and SANS 10254.']}},

{id:'hot-water-loop',cat:'geysers,install',title:'Hot-water circulation / return loop',kw:'hot water circulation return loop recirculating pump dead leg long wait for hot water slow hot water pipe lagging timer warm water pyp sirkulasie',sym:'takes ages for hot water to arrive; wasting water waiting for hot; far bathroom; dead leg',sum:'Cut the wait for hot water at a far tap with a return loop and small pump',
 diagnose:{start:'q1',nodes:{
  q1:{q:'How long does hot water take to arrive at the far tap?',opts:[['More than about 30 seconds and the pipe run is long','r_loop'],['Short wait but hot is lukewarm','r_cool'],['Hot at the geyser, none at the tap','r_block']]},
  r_loop:{res:1,cause:'Long hot-water pipe (dead leg) full of cold water',do:['Insulate the hot pipe first. It helps every way.','Option 1: move the hot water source closer (a second small geyser near the far bathroom).','Option 2: fit a return loop with a small circulation pump on a timer or thermostat.','Explain the extra electricity and the extra heat loss to the customer.'],next:'install'},
  r_cool:{res:1,cause:'Hot pipe losing heat, geyser set too low or a leaking hot tap',do:['Insulate the hot pipes, including in the roof.','Check the thermostat setting (about 60 °C).','Fix dripping hot taps.'],parts:[['Pipe lagging','lagging']]},
  r_block:{res:1,cause:'A valve or airlock on the hot line',do:['See No hot water.','Check isolating valves, flexi hoses and cartridges at that tap.']}}},
 install:{warn:[ELEC_WARN,HOT_WARN],tools:['Pipe cutter','Soldering kit or crimp tool for the pipe type','Spanners','Pipe clips','Lagging'],parts:[['Circulating pump','circulating pump'],['Non-return valve','non return valve'],['Ball valve 22mm','ball valve 22mm'],['Pipe lagging 22mm','lagging 22mm'],['22mm copper pipe','copper pipe 22mm'],['Pipe clips','pipe clip']],
  steps:['Draw the system: geyser, the longest hot run, the far tap or the end of the branch. A return pipe must go from the farthest point back to the geyser return port or the cold feed (follow the pump and geyser maker).','Choose a bronze or stainless steel circulating pump suitable for drinking water, sized for the loop (the maker gives head and flow).','Install the pump on the return line close to the geyser, with isolating valves either side so it can be serviced.','Fit a non-return valve in the return line so hot water cannot flow the wrong way and the cold supply does not circulate through the loop.','Connect the return pipe to the far end of the hot branch (a tee after the last tap on the run).','Insulate the whole loop (supply and return) as it keeps losing heat when it runs.','Fit a timer or a pipe-stat so the pump only runs when hot water is wanted; pumps running all day waste a lot of electricity.','The electrician wires the pump to a protected circuit. Earthing and an Electrical CoC are needed.','Fill, bleed air and run the pump until the whole loop is warm.','Check no cold feed is drawn into the hot line and that all taps still give hot water.','Show the customer the timer and the isolating valves.'],
  sans:['The standards limit how much water can sit in a hot-water pipe before the tap (dead-leg limits) and how hot-water pipes are insulated. Check the current SANS 10252-1 and SANS 10400-XA rules for the exact numbers.','Keep stored hot water at the temperature in the standard to control legionella; do not set the geyser lower to save energy.']}},

{id:'geyser-safety-checklist',cat:'geysers,compliance',title:'Geyser safety checklist (before you leave)',kw:'geyser safety checklist inspect check geyser coc compliance insurance drip tray valves temperature handover geiser veiligheid',sym:'inspect a geyser for insurance; is this geyser safe; geyser compliance check',sum:'A tick-list for a geyser inspection or after any geyser work',
 labels:{repair:'Checklist'},
 repair:{head:'Geyser safety checklist',warn:[ELEC_WARN],tools:['Torch','Camera','Pressure gauge','Thermometer','Ladder (if the geyser is in the roof)'],parts:[['Vacuum breaker','vacuum breaker'],['Safety valve','safety valve'],['Drip tray','geyser tray']],
  steps:['Data plate photographed: make, litres, kPa rating, date.','Supply pressure measured and below the geyser rating (or a pressure control valve is fitted).','Safety (T&P) valve fitted, rated to match the geyser, lever tested, not dripping.','Safety valve drain is metal, full size, falls continuously, 3 bends or fewer, ends in view outside, nothing blocking it.','Vacuum breaker(s) fitted above the top of the geyser and free to breathe.','Isolating valve fitted on the cold feed and it works; the customer knows where it is.','Non-return valve fitted where the maker requires it.','Drip tray fitted, big enough, level, drain to a visible safe place.','Geyser is on a base or brackets that carry its full weight; ceiling and roof structure sound.','Hot pipe and geyser insulated as required; no hot pipes in direct contact with timber.','Thermostat set to about 60 °C; no signs of overheating.','No leaks at joints, flange or valves.','Earth bonding present (electrician) and the Electrical CoC is available.','Plumbing CoC done where required (licensed plumber). Photos stored with the job.'],
  sans:['SANS 10254 and SANS 10252-1 are the references for geyser installations. Insurers often ask for the CoC after a geyser claim.']}},
{id:'solar-geyser-problems',cat:'solar,geysers',title:'Solar geyser problems',kw:'solar geyser panel evacuated tubes thermosyphon pumped controller geyserwise sensor no hot water in winter dripping valve overheating frost glycol sonkrag geiser son',sym:'solar geyser not heating; solar geyser dripping in summer; pump runs but no heat; tubes broken; solar water cold',sum:'No heat, overheating or weeping valves on a solar water heater',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is the solar system doing?',opts:[['Water stays cold on sunny days','q2'],['Valve drips or steams on hot sunny days','r_stag'],['Pump or controller shows a fault or does not run','q3'],['Tube or panel looks broken or leaking','r_panel'],['Water too hot at the taps','r_hot']]},
  q2:{q:'What type is it?',opts:[['Thermosyphon: tank above or next to the panel, no pump','r_syphon'],['Pumped: controller and circulation pump','q3'],['Not sure','r_syphon']]},
  q3:{q:'Does the controller show power and a temperature for the panel and tank?',opts:[['No display or an error code','r_ctrl'],['Display OK, pump does not run when panel is hot','r_pump'],['Pump runs but panel stays cold or tank does not heat','r_air']]},
  r_stag:{res:1,cause:'Stagnation: no hot water is being used, so the panel boils and the safety valve relieves',do:['Check that the safety (T&P) valve rating matches the system and the drain is clear and visible.','Check the expansion arrangement and any pressure control.','Advise the customer: the valve may open on very hot days with low use; if it drips constantly, test pressure and replace a worn valve.','Controllers can run the pump at night to cool the panel (check the maker).'],parts:[['Safety valve','safety valve']],next:'repair'},
  r_panel:{res:1,cause:'Damaged panel or cracked evacuated tube',do:['Close the isolating valves to the panel and make safe against steam.','Photograph the damage.','Replace the tube or panel (maker specific).','Check for frost damage in the pipework.'],next:'repair'},
  r_hot:{res:1,cause:'Hot water from the panel is unmixed; no tempering valve',do:['Fit or check the thermostatic mixing valve on the hot outlet.','Warn the customer about scald risk.'],parts:[['Thermostatic mixing valve','thermostatic mixing valve']],next:'repair'},
  r_syphon:{res:1,cause:'Airlock, blocked or leaking pipework, or a failed backup element/thermostat',do:['Check the cold feed to the tank and that the panel and tank are full of water.','Check the pipes between panel and tank slope upward so air can escape.','Feel the panel flow and return pipes: one hot, one cold means the water is not circulating.','Backup element: the electrician checks it.'],next:'repair'},
  r_ctrl:{res:1,cause:'Controller, sensor or power problem',do:['Check the controller power supply and fuse (electrician).','Check the sensor cables at the controller; a loose or open sensor shows an error.','Test the sensors with the controller test mode (maker).'],call:'electrician',parts:[['Controller','geyserwise'],['Probe','geyserwise probe']],next:'repair'},
  r_pump:{res:1,cause:'Pump or its supply has failed, or the differential setting is wrong',do:['Check the pump power and voltage (12 V or 220 V, depending on the system).','Test by running the pump from the controller test or manual mode.','Check the panel sensor reading against reality.'],call:'electrician',parts:[['Circulating pump','circulating pump']],next:'repair'},
  r_air:{res:1,cause:'Airlock or a blocked loop, or a stuck non-return valve',do:['Bleed the loop at the high point following the maker steps.','Check pipe fall and valves.','Check the non-return valve and strainer.'],next:'repair'}}},
 repair:{warn:[ELEC_WARN,HOT_WARN,'Panels and pipes on a sunny roof can be above 100 °C. Cover the panel before working on it, and work at the cool time of day. Use fall protection on a roof.'],tools:['Ladder and harness','Panel cover','Multimeter (electrician)','Hose','Spanners'],parts:[['Solar geyser','solar geyser'],['Controller','geyserwise'],['Circulating pump','circulating pump'],['Sensor','geyserwise probe'],['Thermostatic mixing valve','thermostatic mixing valve'],['Safety valve','safety valve']],
  steps:['Read the system type and maker instructions. Take photos of the whole system: panel, pipes, controller and valves.','Close the isolating valves and switch off the backup element if you are going to drain anything.','Check that the system is full of water or glycol and the pressure is right for the system type (low pressure or high pressure).','Check each valve: isolating, non-return, safety valve and the vacuum breaker or expansion arrangement.','Check the sensors and wiring (electrician): panel sensor, tank sensor, controller power.','Bleed the pipes at the highest point until water runs without air. Do not open a hot pressurised line without letting it cool.','Cover the damaged tube or panel; replace as per the maker.','Insulate all exposed pipes, with UV-proof lagging outside.','Start the system and check the pump runs and the flow and return pipes warm up.','Check again after a sunny afternoon, including the safety valve drain.'],
  sans:['SANS 10254 and the maker instructions govern a solar installation with an electric backup element.','Check which parts of SANS 10252-1 and SANS 10400-XA apply to solar and heat-pump hot water on new buildings.']}},

{id:'heat-pump-geyser',cat:'solar,geysers,install',title:'Heat pump hot water',kw:'heat pump geyser airflow compressor fan defrost cop evaporator condensate low output cold weather installation warmtepomp',sym:'heat pump not heating; heat pump noisy; installing a heat pump; heat pump trips',sum:'Quick diagnosis and installation checks for an air-source heat pump geyser',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is the heat pump doing?',opts:[['No heat, no fan or compressor','r_pow'],['Fan runs, little heat','r_air'],['Compressor starts and stops or an error shows','r_err'],['Water leaks around it','r_leak']]},
  r_pow:{res:1,cause:'No power or a tripped protection device',do:['Check the heat pump breaker and isolator.','Check the controller and its fuse.','Electrician tests the supply and earth.'],call:'electrician'},
  r_air:{res:1,cause:'Blocked airflow, dirty evaporator or very low outside temperature',do:['Clear leaves and dirt from the air intake and outlet.','Clean the evaporator fins gently (power off).','Check the clearances around the unit with the maker.','Tell the customer output drops in cold weather; the element backup takes over.'],next:'install'},
  r_err:{res:1,cause:'Sensor, refrigerant or compressor fault',do:['Read the error code in the manual.','Do not open the refrigerant circuit.','Call the maker agent. Refrigerant work needs a qualified technician.'],call:'electrician'},
  r_leak:{res:1,cause:'Condensate drain blocked or a plumbing joint leaks',do:['Check the condensate drain and that it falls away.','Check the water connections and valves.','Replace the leaking fitting.'],parts:[['Heat pump drain cock','heat pump'],['Banjo valve','heat pump banjo']],next:'install'}}},
 install:{warn:[ELEC_WARN,'Refrigerant circuits are sealed. Do not cut or vent them. Only a qualified refrigeration technician may open them.'],tools:['Spanners','Level','Pipe cutter','Hose','Multimeter (electrician)'],parts:[['Heat pump','heat pump'],['Banjo valve','heat pump banjo'],['Drain cock','heat pump draincock'],['Isolating valve','ball valve 22mm'],['Non-return valve','non return valve'],['Pipe lagging','lagging']],
  steps:['Choose the position: free airflow around the intake and outlet, a firm level base, and away from bedroom windows (noise).','Read the maker instructions: clearances, maximum pipe lengths, condensate drain and the electrical supply.','Fix the unit on its base. Make a condensate drain with a fall to a safe place.','Connect cold in, hot out and the pipework between the unit and the cylinder as the maker shows. Insulate all pipes.','Fit the maker valve block: isolating valve, safety valve with a visible metal drain, drain cock and expansion arrangement.','The electrician makes the supply, protection and earthing; an Electrical CoC is needed.','Fill the cylinder and bleed all air before any power goes on.','Set the thermostat and the schedule (the maker). Check the backup element works.','Run the unit and check it makes hot water, drains condensate and does not vibrate.','Explain to the customer: output is lower in the coldest weather; keep the air intake clear.'],
  sans:['SANS 10254: the water heater installation rules still apply (safety valve, drip tray, drain).','SANS 10400-XA (energy use) asks for a share of hot water energy from other than direct electric resistance in new homes. Check the current rule.']}},

{id:'gas-geyser',cat:'solar',title:'Gas geyser (instant LPG water heater)',kw:'gas geyser lpg instant water heater flue pilot ignition cylinder cut out low flow carbon monoxide gaskraan gas verwarmer',sym:'gas geyser wont light; smell of gas; gas heater cuts out; no hot water gas; flue',sum:'Symptoms and what a plumber may and may not do on a gas geyser',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Do you smell gas?',opts:[['Yes, or I hear hissing','r_gas'],['No','q2']]},
  q2:{q:'What is the problem?',opts:[['Does not light, no clicking','r_batt'],['Lights then goes out','r_flame'],['Hot water is lukewarm','r_flow'],['Soot, yellow flame or headaches','r_co']]},
  r_gas:{res:1,cause:'Gas leak',do:['No flames, no switches, no phones near the leak.','Open windows and doors; close the cylinder valve only if it is safe.','Leave the area and call a registered gas installer or the emergency services.'],call:'gas'},
  r_co:{res:1,cause:'Poor combustion or blocked flue: carbon monoxide risk',do:['Switch the appliance OFF and close the gas.','Open windows, take people outside if they feel dizzy or sick.','Do not use it again until a registered gas installer has serviced it.'],call:'gas'},
  r_batt:{res:1,cause:'Batteries flat, no water flow to start it, or ignition fault',do:['Replace the batteries (if the maker allows the user to do it).','Check the isolating valve and the cold water supply are open.','If it still does not start: gas installer.'],call:'gas'},
  r_flame:{res:1,cause:'Flame failure, flue draught problem, low gas pressure or dirty burner',do:['Check the cylinder is not empty and the regulator is fine.','Do not clean or adjust the burner yourself.','Gas installer to inspect.'],call:'gas'},
  r_flow:{res:1,cause:'Water flow or pressure too low for the appliance, or scale in the heat exchanger',do:['Check water pressure and flow with the taps; clean the aerators.','Check the isolating valve and filters at the inlet.','Scale: a descaling service by the installer.'],call:'gas',parts:[['Inline filter','inline filter']]}}},
 install:{warn:[GAS_WARN,'The plumber supplies and connects the water side only if allowed. The gas pipework, flue, ventilation and commissioning belong to the registered gas installer.'],tools:['Spanners','Pipe cutter','Level','Camera'],parts:[['Gas geyser','gas geyser'],['Installation kit','gas geyser installation kit'],['Flue','gas geyser flue'],['Isolating valve','ball valve 15mm'],['Pressure control valve','pcv']],
  steps:['Check the position with the gas installer: a gas heater needs a flue to the outside and ventilation, and some rooms (bedrooms, bathrooms) are restricted unless the appliance is room-sealed. The installer decides.','Check the water pressure and flow suit the model. Fit a pressure control valve if the pressure is too high.','Fix the appliance on a solid wall at the maker height.','Connect cold in and hot out with unions and an isolating valve. Insulate the hot pipe.','Fit a water filter if the water is dirty.','The registered gas installer: gas supply, regulator, flue, ventilation, leak test and the gas Certificate of Conformity.','Test water flow and temperature. Flush the lines first.','Explain to the customer: never block the flue or vents, service every year, keep the cylinder upright and outdoors.'],
  sans:['LP gas installations follow SANS 10087-1. The installer issues a gas CoC. Check the current standard.','Plumbing water-side work follows SANS 10252-1.']}},

{id:'instant-geyser',cat:'solar,geysers',title:'Instant (tankless) water heater',kw:'instant geyser tankless water heater electric instant boiler shower heater flow switch element cold shower kw cable stiebel ariston kwikot geiser oombliklik',sym:'instant geyser only lukewarm; instant heater trips; no hot water from tankless; tankless installation',sum:'Diagnose or install an electric instant water heater',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is it doing?',opts:[['No heat at all','q2'],['Lukewarm or goes cold when more taps open','r_flow'],['Trips the breaker','r_trip'],['Leaks','r_leak']]},
  q2:{q:'Is there water flow at the heater (taps open, inlet valve open) and does the heater click when the tap opens?',opts:[['Water flows and it clicks, no heat','r_elem'],['Water flow is weak or no click','r_pres']]},
  r_flow:{res:1,cause:'The heater is too small for the flow, or the flow is too high',do:['Check the flow rating of the heater in L/min and the number of taps.','Reduce the flow with a restrictor, or use one heater per point.','Check the inlet strainer and aerators for blockage.'],parts:[['Inline filter','inline filter']]},
  r_trip:{res:1,cause:'Electrical fault or an overloaded circuit',do:['Switch off at the DB.','Electrician checks the cable size, breaker rating and earth leakage.'],call:'electrician'},
  r_leak:{res:1,cause:'Failed seal or fitting',do:['Isolate water and power.','Replace the fitting or the seal; if the unit is leaking, replace it.'],call:'electrician'},
  r_elem:{res:1,cause:'Element, thermal cut-out or control failure',do:['Isolate power. Electrician tests the elements and cut-out.','Replace parts per the maker, or replace the heater.'],call:'electrician'},
  r_pres:{res:1,cause:'Water pressure or flow too low to trip the flow switch, or a blocked inlet filter',do:['Clean the inlet filter.','Measure pressure; instant heaters need a minimum pressure (see maker).','Check the isolating valve.'],parts:[['Inline filter','inline filter']]}}},
 install:{warn:[ELEC_WARN,'Instant heaters draw a large current (many kW). The electrician must check the cable size, breaker and earth leakage.'],tools:['Spanners','Pipe cutter','Drill and plugs','Level'],parts:[['Instant water heater','instant geyser'],['Isolating valve','ball valve 15mm'],['Inline filter','inline filter'],['Flexi hose','flexi 350'],['Safety valve','safety valve']],
  steps:['Read the maker instructions: kW, flow range, minimum pressure and whether it can be fed from a high-pressure supply.','Choose a position near the point of use, easy to reach, away from direct spray, on a solid wall.','Fit an isolating valve and a strainer or filter on the cold feed.','Connect cold and hot with flexi or copper connections. Do not put a valve on the hot outlet of an unvented heater unless the maker allows it.','Run water through the heater with the power OFF until all air is out. Never switch an element on dry.','The electrician makes the dedicated circuit with the correct cable, breaker and earth leakage and an Electrical CoC.','Test the temperature rise and the flow.','Fit a mixing valve if the heater can deliver very hot water.'],
  sans:['SANS 10142-1 (wiring code) applies to the supply circuit; ask the electrician for the CoC.','Plumbing follows SANS 10252-1; follow the maker for the hot-side rules.']}},

{id:'tap-washer-cartridge',cat:'taps',title:'Tap washer or cartridge replacement',kw:'tap washer cartridge replace dripping tap o-ring headpart spindle seat reseat ceramic disc quarter turn bibtap pillar tap kraan wasser kartrij',sym:'tap drips when closed; tap stiff; tap leaks from the handle; tap will not close fully',sum:'Fix a dripping tap by replacing the washer, seat or cartridge',
 repair:{warn:['Close the water first. Open the tap to release pressure. Mark which side is hot and which is cold if the handles are not marked.'],tools:['Adjustable spanner','Screwdrivers','Allen keys','Tap reseating tool (optional)','Cloth to protect chrome','PTFE tape','Bucket'],parts:[['Tap washer','tap washer'],['Tap cartridge','tap cartridge'],['Headpart','headpart'],['Angle valve','angle valve'],['Silicone sealer','silicone']],
  steps:['Close the isolating (angle) valve below the tap, or the room valve. Open the tap to drain and relieve pressure.','Put a cloth over the sink and plug the waste so small parts cannot fall in.','Remove the cap and handle screw (it can be under a small cap), then lift off the handle and shroud.','Undo the headpart or cartridge with a spanner. Use a cloth to protect the chrome.','Washer tap: pull out the headpart and fit a new washer of the same size (flat or tapered) and, if the seat is scored, reseat or replace the seat.','Ceramic disc or quarter-turn cartridge: replace the whole cartridge with the same type (check the number of splines and the height).','Replace worn O-rings on the spindle; grease them lightly.','Reassemble in the reverse order. Keep the cartridge in the open or closed position the maker shows.','Open the isolating valve slowly with the tap open to flush debris.','Close the tap and check for drips for 10 minutes; check under the sink for leaks.','Replace the cap and tell the customer that a tap which keeps wearing may need replacing.'],
  sans:['SANS 10252-1: an isolating valve at every fixture is good practice so taps can be serviced without closing the whole house.']},
 diagnose:{start:'q1',nodes:{
  q1:{q:'Where does it leak?',opts:[['From the spout when the tap is closed','r_spout'],['From around the handle or spindle','r_spindle'],['From the base of the tap or under the basin','r_base'],['The tap is stiff or hard to close','r_stiff']]},
  r_spout:{res:1,cause:'Worn washer or seat (washer tap) or worn cartridge (mixer)',do:['Replace the washer or cartridge.','Reseat or replace a scored seat.'],parts:[['Tap washer','tap washer'],['Tap cartridge','tap cartridge']],next:'repair'},
  r_spindle:{res:1,cause:'Worn O-ring or gland packing',do:['Replace the O-ring or packing in the headpart.','Tighten the gland nut gently.'],parts:[['Headpart','headpart']],next:'repair'},
  r_base:{res:1,cause:'Loose fixing nut, perished base seal or a flexi hose leak',do:['Check the flexi hoses and angle valves for drips.','Re-seat the tap with new washers.'],parts:[['Flexi hose','flexi 350']],next:'repair'},
  r_stiff:{res:1,cause:'Scale or dry O-rings',do:['Clean and grease the spindle.','Replace the cartridge if it is worn.'],parts:[['Tap cartridge','tap cartridge']],next:'repair'}}}},

{id:'shower-mixer-cartridge',cat:'bath,taps',title:'Shower mixer or cartridge replacement',kw:'shower mixer cartridge replace concealed built-in wall mixer handle escutcheon diverter stuck cold hot mixing only hot only no mixing stort kraan kartrij',sym:'shower mixer stiff; only hot or only cold; shower drips after turning off; diverter stuck',sum:'Replace a shower cartridge or the whole concealed mixer',
 repair:{warn:['Close the supply before touching the cartridge. Check the isolating valves work first. Tiles: do not force or hammer.'],tools:['Allen keys','Screwdrivers','Pliers','Cartridge puller (if the maker has one)','Cloth','Camera'],parts:[['Shower cartridge','shower cartridge'],['Shower mixer','shower mixer'],['Bath/shower mixer','bath mixer'],['Silicone','silicone'],['PTFE tape','ptfe tape']],
  steps:['Identify the mixer make and model (photo of the handle and escutcheon). Cartridges are not universal.','Close the supply: isolating valves on the mixer or the room valve. Open the mixer to relieve pressure.','Remove the handle (grub screw under a cap or button), then the escutcheon plate.','Take off the retaining clip, nut or bonnet and pull out the cartridge, using the maker puller if it is stuck.','Compare the old and new cartridge (splines, length, hot/cold marking). Fit the new one in the same orientation.','Replace the O-rings and lubricate with silicone grease.','Refit the retaining clip, escutcheon and handle. Set the handle stops for the right maximum temperature.','Open the supply slowly. Check hot and cold are the right way round and the diverter works.','Check for leaks at the wall and the spout. Seal the escutcheon to the tiles with sanitary silicone if the maker allows.','If the whole mixer body is leaking or corroded, quote a new mixer and open the wall carefully.'],
  sans:['Hot is on the left and cold on the right as a convention. Check the markings; a mixer fitted the wrong way gives cold when hot is selected.']},
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is wrong with the shower mixer?',opts:[['Stiff or will not move','r_stiff'],['Only hot or only cold, will not mix','r_cart'],['Drips from the shower head after turning off','r_cart'],['Diverter sticks (water goes to the bath instead of the shower)','r_div'],['Leaks from behind the handle','r_seal']]},
  r_stiff:{res:1,cause:'Scale in the cartridge',do:['Remove, soak in a descaler and regrease; if still stiff, replace.'],parts:[['Shower cartridge','shower cartridge']],next:'repair'},
  r_cart:{res:1,cause:'Worn cartridge or one blocked inlet',do:['Check the hot and cold supply pressure and the isolating valves.','Check for blocked inlet screens.','Replace the cartridge.'],parts:[['Shower cartridge','shower cartridge']],next:'repair'},
  r_div:{res:1,cause:'Worn diverter seal or scaled diverter',do:['Replace the diverter cartridge or seals (maker specific).'],parts:[['Shower cartridge','shower cartridge']],next:'repair'},
  r_seal:{res:1,cause:'Worn O-ring or a cracked body',do:['Isolate and replace the cartridge O-rings.','If the body leaks, replace the mixer.'],parts:[['Shower mixer','shower mixer']],next:'repair'}}}},

{id:'showerhead-low-flow',cat:'bath,pressure',title:'Shower head low flow or spraying sideways',kw:'shower head low flow weak shower trickle blocked rose scale sideways spray flow restrictor hose aerator stort swak water druk',sym:'weak shower; spray goes in all directions; shower pressure low only in shower; low flow showerhead',sum:'Clean or replace the shower head and check the supply',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Is only the shower weak, or other taps too?',opts:[['Only the shower','q2'],['All hot taps','r_hot'],['All taps in the house','r_all']]},
  q2:{q:'Is the shower head clean? Unscrew it (or lift the hose) and run the water.',opts:[['Water runs strongly without the head','r_head'],['Still weak without the head','r_mixer']]},
  r_head:{res:1,cause:'Scale or debris in the shower head or flow restrictor',do:['Remove the head and the small filter washer.','Soak in descaler or vinegar and brush the nozzles.','Remove the flow restrictor only if the maker allows it; fit a new head if it is worn.'],parts:[['Shower head','shower head'],['Shower hose','shower hose'],['Shower rose','shower rose']]},
  r_mixer:{res:1,cause:'Blocked inlet to the mixer, partly closed isolating valve or a worn cartridge',do:['Check the isolating valves are fully open.','Check the cartridge inlets for debris.','Check the pipe sizes and bends.'],parts:[['Shower cartridge','shower cartridge']]},
  r_hot:{res:1,cause:'Hot side restricted: geyser outlet, valves or a blocked non-return valve',do:['See Low water pressure and No hot water.','Check the geyser isolating valve and any strainer on the hot side.'],parts:[['Non-return valve','non return valve']]},
  r_all:{res:1,cause:'Supply pressure or flow problem',do:['See Low water pressure.','Measure the pressure at an outside tap.'],parts:[['Pressure gauge','pressure gauge']]}}},
 repair:{tools:['Spanner','Cloth','Descaler or vinegar and a bucket','Soft brush','New shower hose or head'],parts:[['Shower head','shower head'],['Shower hose','shower hose'],['Shower rose','shower rose'],['PTFE tape','ptfe tape']],
  steps:['Close the shower and unscrew the head (cloth around the chrome nut).','Remove the small washer filter and any flow restrictor; rinse them.','Soak the head in descaler or vinegar until the scale softens; brush the nozzles gently.','Flush the pipe or hose into a bucket for a few seconds before refitting.','Refit with a new fibre washer; use thread tape on tapered threads only.','Check the hose is not kinked and the wall bracket fits.','Test for flow, spray pattern and leaks at the joints.','If flow is still low, check the supply pressure and the mixer as in the Diagnose tab.']}},

{id:'shower-leak',cat:'bath,leaks',title:'Shower leak (wall, floor, waste or mixer)',kw:'shower leak leaking wall damp tiles grout waterproofing waste seal tray ceiling below stain mould shower door silicone stort lek vog',sym:'water coming through the ceiling below the shower; damp wall next to shower; mouldy grout; shower tray leaks',sum:'Find where the water escapes and fix the right thing',
 diagnose:{start:'q1',nodes:{
  q1:{q:'When does the leak show?',opts:[['Only when the shower runs','q2'],['Even when the shower is off','r_pipe'],['Only after the shower, from the floor edge','r_floor']]},
  q2:{q:'Block the shower waste, run a few cm of water on the floor, wait 30 minutes. Does it leak now?',hint:'Do not leave it unattended.',opts:[['Yes, with water standing on the floor','r_floor'],['No, but it leaks when the shower sprays','q3']]},
  q3:{q:'Where does the spray hit, and is the grout or the sealant perished?',opts:[['Grout or sealant is cracked or missing','r_seal'],['Around the mixer or shower arm','r_pipe'],['Not sure','r_pipe']]},
  r_pipe:{res:1,cause:'A leaking pipe, joint or mixer behind the wall',do:['Close the water to the shower and watch the meter.','Pressure test the shower pipes (see Hidden leak hunt).','Open the wall as little as possible, fix the pipe and make good.'],parts:[['Shower mixer','shower mixer'],['Copper elbow','copper elbow 22mm']],next:'repair'},
  r_floor:{res:1,cause:'Failed waterproofing, waste seal or tray joint',do:['Check the waste connection and the seal around the shower waste.','Reseal the waste and tray edge.','If waterproofing has failed (membrane), the floor must be lifted, waterproofed and retiled.'],parts:[['Shower waste','shower waste'],['Waterproof','waterproof'],['Sealant','sealant']],next:'repair'},
  r_seal:{res:1,cause:'Perished grout or silicone',do:['Remove the old silicone and loose grout.','Clean and dry the area.','Re-grout with water-resistant grout and fit new sanitary silicone.'],parts:[['Silicone','silicone'],['Sealant','sealant']],next:'repair'}}},
 repair:{warn:['Let the area dry fully before sealing. Damp behind tiles hides leaks and mould. Tell the customer that making good (tiling, painting) is a separate cost.'],tools:['Silicone gun','Grout rake','Spirit level','Moisture meter (if you have one)','Test plug','Camera'],parts:[['Silicone','silicone'],['Sealant','sealant'],['Shower waste','shower waste'],['Waterproofing','waterproof']],
  steps:['Photograph the damage and the room below (ceiling stain).','Stop using the shower. Close the shower water if a pipe leaks.','Do the shower floor flood test: block the waste with a test plug, run 20 to 30 mm of water, mark the level and wait.','Check below the shower for drips during the test. If it drips only at the waste, reseal or replace the waste seal.','If the water level falls but the waste is dry, the membrane or tray has failed.','If the leak is spray-only, clean and re-seal the grout, the corners and the door track.','If a pipe leaks, find it and repair it (see Hidden leak hunt). Open tiles with a chisel, not a hammer-drill.','Pressure test the repaired pipework for at least 15 minutes before closing up.','Leave the wall open for 24 hours if you can, to dry and check again.','Make good and recheck the ceiling below after the next shower.'],
  sans:['Showers need a falling, waterproof floor draining to the waste. Check the current waterproofing rules and the maker instructions.']}},

{id:'bidet',cat:'bath,install',title:'Bidet installation',kw:'bidet install connect mixer wall mounted floor spray backflow hot cold basin mixer ascending spray waste 32mm bidee',sym:'fit a bidet; bidet mixer; bidet backflow',sum:'Fit a floor or wall bidet with mixer, waste and backflow protection',
 install:{warn:['A bidet can draw dirty water back into the supply if the spray is under water. Use a bidet mixer or fitting designed for that and follow the backflow rules.'],tools:['Basin spanner','Drill and masonry bit','Spirit level','Silicone gun','Spanners','PTFE tape'],parts:[['Bidet','bidet'],['Basin trap / bottle trap','bottle trap'],['Angle valve','angle valve'],['Flexi hose','flexi 350'],['Basin mixer','basin mixer'],['Fixing set','pan fixing'],['Silicone','silicone']],
  steps:['Choose the bidet type: floor-mounted or wall-hung, with the tap hole layout your mixer needs.','Mark the position: keep comfortable clearance to the wall and the other fixtures, and check the maker installation sheet for the minimum distances.','Fit the mixer and waste to the bidet before mounting it.','Fix the bidet to the floor or wall with the correct plugs and bolts; do not over-tighten (porcelain).','Fit angle valves on hot and cold and new flexi hoses.','Connect the trap and waste (usually 32 or 40 mm) with a fall to the drain.','Check the fitting suits the pressure system (low-pressure or high-pressure mixers).','Open the valves slowly and check every joint dry. Run hot and cold.','Check for backflow protection: the maker mixer includes it or you must fit a vacuum breaker or the arrangement the standard requires.','Seal to the floor and wall with sanitary silicone; show the customer the angle valves.'],
  sans:['SANS 10252-1: backflow protection is required for fittings where the outlet can be submerged or the spray can be below the rim. Check the current rules for bidets.','SANS 10252-2: trap fitted with a water seal; waste branch fall of at least 1:46; vent if the trap outlet is more than 6 m of pipe from a ventilated stack.']}},

{id:'toilet-fill-valve',cat:'toilets',title:'Toilet cistern fill valve (float valve) replacement',kw:'toilet fill valve float valve inlet valve cistern filling hissing noisy water level overflow replace side entry bottom entry ball cock toilet vul klep vlot',sym:'cistern keeps filling; hissing toilet; water runs into the overflow; slow to fill; noisy cistern',sum:'Replace a worn or noisy inlet (float) valve',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What does the cistern do?',opts:[['Water keeps running into the overflow','r_level'],['Hisses after flushing and then stops','r_noise'],['Very slow to refill','r_slow'],['Leaks from under the cistern','r_leak']]},
  r_level:{res:1,cause:'Float set too high, worn seal on the fill valve or dirt in the valve',do:['Lift the float arm or press the float down: if the water stops the float setting is wrong.','Lower the float or the water level setting.','If it still runs: clean or replace the fill valve washer or the whole valve.'],parts:[['Fill valve','fill valve'],['Float valve','float valve']],next:'repair'},
  r_noise:{res:1,cause:'Worn washer or a high supply pressure',do:['Replace the fill valve or washer.','Check the supply pressure; a pressure control valve may be needed.'],parts:[['Fill valve','fill valve']],next:'repair'},
  r_slow:{res:1,cause:'Angle valve not fully open or blocked fill valve',do:['Open the angle valve fully.','Clean the fill valve inlet filter.','Replace the valve if the flow is still low.'],parts:[['Angle valve','angle valve'],['Fill valve','fill valve']],next:'repair'},
  r_leak:{res:1,cause:'Leaking fill valve shank washer or supply connector',do:['Replace the washer or the flexi hose and the shank seal.'],parts:[['Flexi hose','flexi 350'],['Fill valve','fill valve']],next:'repair'}}},
 repair:{warn:['Porcelain and plastic cisterns crack if you over-tighten. Hand-tight plus a quarter turn.'],tools:['Adjustable spanner','Bucket and sponge','Screwdriver','Towel','PTFE tape'],parts:[['Fill valve','fill valve'],['Float valve','float valve'],['Angle valve','angle valve'],['Flexi hose','flexi 350'],['Cistern washer','cistern washer']],
  steps:['Close the angle valve. Flush to empty the cistern and sponge out the rest.','Place a bucket under the supply connection. Disconnect the flexi hose from the fill valve.','Unscrew the plastic locking nut under the cistern and lift the old valve out.','Check the new valve is the same type: side entry or bottom entry, and the height range.','Fit the new valve in the hole with its washer, tighten the nut by hand plus a quarter turn.','Adjust the valve height so the top of the valve is above the overflow level (maker instructions).','Fit a new flexi hose and connect it; tighten until it seals.','Open the angle valve slowly, let the cistern fill and set the float so the water stops at the water-line mark, below the overflow.','Flush a few times and check that it fills, shuts off and does not hiss.','Check the supply connection and the nut dry after 10 minutes. Show the customer the angle valve.'],
  sans:['Cisterns need an overflow that discharges safely and a working shut-off. The water level should stay below the overflow pipe by the maker setting.']}},

{id:'toilet-flush-valve',cat:'toilets',title:'Toilet flush valve or mechanism not working',kw:'toilet flush valve flush mechanism dual flush button cable lever arm syphon beta valve outlet valve seal washer weak flush stuck handle flush pipe cone spoel meganisme',sym:'toilet will not flush; weak flush; handle loose; water leaks past the flush valve into the pan; button stuck',sum:'Replace or adjust the flush valve, seal, button or lever',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What does the toilet do?',opts:[['Handle or button does nothing','r_link'],['Weak flush, bowl does not clear','r_weak'],['Water trickles into the pan all the time','r_seal'],['Flushes, but water keeps running','r_stop']]},
  r_link:{res:1,cause:'Broken cable, lever arm or push button linkage',do:['Remove the lid and look at the linkage while someone presses the button.','Replace the lever, cable or mechanism.'],parts:[['Dual flush mechanism','dual flush mechanism'],['Cistern lever','cistern lever'],['Flush button','dual flush button']],next:'repair'},
  r_weak:{res:1,cause:'Water level too low, partly blocked pan holes or a worn flush valve',do:['Set the water level to the cistern mark.','Clean under the rim of the pan.','Check the flush pipe cone and seal.'],parts:[['Flush pipe cone','flush cone'],['Flush valve','flush valve']],next:'repair'},
  r_seal:{res:1,cause:'Worn or dirty flush valve seal (the phantom flush)',do:['Replace the seal or the whole flush valve.','Put colouring in the cistern to confirm.'],parts:[['Flush valve','flush valve'],['Cistern washer','cistern washer']],next:'repair'},
  r_stop:{res:1,cause:'Fill valve not shutting off, or a flush valve that does not seat',do:['See Toilet fill valve and Running toilet.'],parts:[['Fill valve','fill valve']],next:'repair'}}},
 repair:{warn:['Close the water and empty the cistern first. Porcelain cracks if over-tightened.'],tools:['Adjustable spanner','Sponge and bucket','Screwdriver','Towel'],parts:[['Dual flush mechanism','dual flush mechanism'],['Flush valve','flush valve'],['Cistern washer','cistern washer'],['Cistern bolt set','cistern bolt'],['Flush pipe cone','flush cone']],
  steps:['Close the angle valve, flush and sponge the cistern dry.','Photograph the mechanism and identify the make (Geberit, Dutton, Wirquin etc.).','Disconnect the supply hose if the cistern needs to be removed. Remove the lid carefully.','Remove the button or lever, then the linkage or cable.','Undo the flush valve locking nut under the cistern and lift the valve out (concealed cistern: use the service hatch and maker steps).','Fit the new flush valve or mechanism and a new seal; tighten by hand plus a quarter turn.','Adjust the height and the cable so the valve lifts fully but does not stick.','Refill, set the water level to the mark and flush several times.','Check the cistern, the pan connection and all nuts dry for 10 minutes.','Leave the customer the old parts if they ask. Show how the dual button works.']}},

{id:'toilet-leaking-base',cat:'toilets,leaks',title:'Toilet leaking at the base or pan connection',kw:'toilet leaking base pan connector floor wet around toilet cracked pan wax seal seal ring close coupled bolts cistern bolts condensation wc lek vloer',sym:'water around the bottom of the toilet; wet floor next to toilet; smell near the toilet base; wobbly toilet',sum:'Find the source: cistern, supply, pan outlet seal or floor fixing',
 diagnose:{start:'q1',nodes:{
  q1:{q:'When is the floor wet?',opts:[['After a flush','q2'],['All the time, even when idle','q3'],['Only on cold humid days, drips from the cistern body','r_cond']]},
  q2:{q:'Dry the area and mop. Flush once and watch the base and the cistern joint.',opts:[['Water comes from under the pan at the floor','r_seal'],['Water drips at the back between the cistern and pan','r_cc'],['Water comes from the cistern bolts','r_cc']]},
  q3:{q:'Is the angle valve, flexi hose or supply joint dripping?',opts:[['Yes','r_supply'],['No, dry','r_overflow']]},
  r_seal:{res:1,cause:'Failed pan connector or seal at the drain, or loose or cracked pan',do:['Close the water, flush to empty and lift the pan (or the cistern first).','Replace the pan connector, seal ring and check the soil pipe end.','Refit the pan, fix to the floor with new fixings.'],parts:[['Pan connector','pan connector'],['Pan seal ring','pan seal'],['Pan fixing','pan fixing']],next:'repair'},
  r_cc:{res:1,cause:'Perished cistern-to-pan washer or loose cistern bolts',do:['Empty the cistern, replace the big rubber washer and the cistern bolt washers.','Tighten evenly by hand plus a quarter turn.'],parts:[['Cistern bolt set','cistern bolt'],['Cistern washer','cistern washer']],next:'repair'},
  r_supply:{res:1,cause:'Leaking supply connection',do:['Replace the flexi hose or washer; tighten the angle valve union.'],parts:[['Flexi hose','flexi 350'],['Angle valve','angle valve']],next:'repair'},
  r_overflow:{res:1,cause:'Overflowing cistern, wet floor from another source, or a leaking sewer joint below',do:['Check the water level against the overflow.','Check pipes in the wall or floor with a meter test.'],next:'repair'},
  r_cond:{res:1,cause:'Condensation on the cistern body',do:['Insulating cistern liners, ventilation and a dry floor stop the drips.','Not a plumbing fault; explain to the customer.']}}},
 repair:{warn:[HYG_WARN,'Porcelain cracks if you over-tighten. Two people to lift a pan.'],tools:['Adjustable spanners','Screwdrivers','Drill and bits for the floor fixings','Sponge, bucket, towels','Gloves and glasses','Silicone gun'],parts:[['Pan connector','pan connector'],['Pan seal ring','pan seal'],['Pan fixing kit','pan fixing'],['Cistern bolt set','cistern bolt'],['Silicone','silicone']],
  steps:['Close the angle valve, flush to empty the cistern and sponge out the rest. Disconnect the supply hose.','Unbolt the cistern (close-coupled) and lift it off; place it on a towel.','Unscrew the pan from the floor and pull it away from the soil pipe. Stuff a rag into the soil pipe opening against smell.','Inspect the pan outlet, the old connector or ring and the soil pipe end for cracks or damage. Clean the surfaces.','Fit a new connector or seal ring and lubricate lightly. Make sure the soil pipe end is circular and undamaged.','Set the pan in place and mark and drill new floor fixings if the old ones are loose.','Fix the pan with the correct plugs and bolts. Do not over-tighten.','Fit the cistern with new washers and bolts; reconnect the water.','Flush several times. Check the base, the cistern joint and the supply for leaks.','Seal the base with silicone only if the customer wants it, and leave the back open if the maker advises.']}},

{id:'urinal',cat:'toilets,install',title:'Urinal installation and faults',kw:'urinal flush valve cistern auto flush timed flush waste dome trap spreader blocked smells waterless urinaal',sym:'urinal does not flush; urinal smells; urinal blocked; install a urinal',sum:'Fit or repair a wall-hung urinal',
 repair:{warn:[HYG_WARN],tools:['Spanners','Drill and masonry bits','Spirit level','Silicone gun','Gloves'],parts:[['Urinal','urinal'],['Urinal flush valve','urinal flush valve'],['Urinal waste','urinal waste'],['Urinal trap','urinal trap'],['Spreader','urinal spreader']],
  steps:['Find the fault: no flush (valve, cistern or supply), weak flush (blocked spreader or low pressure), blocked (scale and uric salts in the trap), smell (trap seal lost or dry).','Close the water. Open the flush valve cap or lift the lid to clean the seat and the diaphragm.','Replace the diaphragm, piston or valve if it is worn.','Clean the spreader holes and the urinal bowl. Descale the trap and waste.','Check the trap holds its water seal and the waste falls to the drain.','Refit, open the water slowly, and check the flush covers the whole bowl.','Set the flush time or interval (a timed cistern or flush valve): the maker advises.']},
 install:{warn:[HYG_WARN],tools:['Spanners','Drill and masonry bits','Spirit level','Tape measure','Silicone gun'],parts:[['Urinal','urinal'],['Flush valve','urinal flush valve'],['Urinal waste','urinal waste'],['Urinal trap','urinal trap'],['Spreader','urinal spreader']],
  steps:['Mark the position: set the bowl lip at a height suited to the users (check the maker sheet and the building rules for heights and spacing).','Mark the supply and waste points on the wall and check the waste outlet position.','Fit the supply with an isolating valve and the flush valve or the cistern for the type of urinal.','Fix the urinal with the brackets on a solid wall.','Connect the spreader, trap and waste to the drain with a fall.','Flush and test; check for leaks and that the spray reaches the whole bowl.','Seal to the wall with sanitary silicone.'],
  sans:['SANS 10252-2: trap and waste sized for the fixture, fall of at least 1:46 on waste, vent if the trap outlet is more than 6 m from a ventilated stack. Check the current standard for urinal flush rules.']}},
{id:'trap-smell-basin-waste',cat:'drainage,bath',title:'Smell from a basin, bath or shower waste (trap)',kw:'trap smell basin waste bad smell stink stank sewer gas p trap s trap bottle trap dry trap siphoned trap seal gurgling bubbling waste pipe smell wasbak reuk stink sifon',sym:'smell from the basin; gurgling when the bath empties; smell from the shower drain; water seal gone',sum:'Why the water seal is lost and how to fix a smelly trap',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Is the fixture used often?',opts:[['No, rarely used, guest bathroom or holiday house','r_dry'],['Yes, used daily','q2']]},
  q2:{q:'Do you hear gurgling or see the water sucked out of the trap when another fixture empties?',opts:[['Yes','r_vent'],['No','q3']]},
  q3:{q:'Take the trap apart and look: is it clogged with hair and sludge, or is the water level low?',opts:[['Clogged or slimy','r_clean'],['Clean, but the smell is still there','r_leak']]},
  r_dry:{res:1,cause:'The water seal has evaporated',do:['Run water into the trap for a minute to refill the seal.','For a seldom-used drain, add a little cooking oil on top to slow evaporation.','Remind the customer to run the water weekly.'],next:'repair'},
  r_vent:{res:1,cause:'Siphonage or back-pressure from poor venting, a long or flat waste, or a trap that is too far from the vent',do:['Check the waste length, fall and the position of the vent or air admittance valve.','A vent or an approved air admittance valve may be needed; check the municipality.','A bottle trap with a long, flat waste is more likely to siphon.'],parts:[['Air admittance valve','air admittance valve'],['Bottle trap','bottle trap']],next:'repair'},
  r_clean:{res:1,cause:'Sludge in the trap and the waste pipe',do:['Remove the trap, clean it and flush the waste.','Check the trap is clean and re-fit with new washers.'],parts:[['Bottle trap','bottle trap'],['P-trap','p trap'],['Basin trap','basin trap']],next:'repair'},
  r_leak:{res:1,cause:'A loose or cracked trap joint, a missing wall seal, or an open pipe end behind the wall',do:['Check each joint for damp and for a smell from the wall opening.','Seal the pipe through the wall with a cap seal or sealant.','If the smell is from the drain outlet itself, see Sewer smell.'],next:'repair'}}},
 repair:{warn:[HYG_WARN],tools:['Bucket','Gloves','Pliers','Spanner','Brush','Camera'],parts:[['Bottle trap','bottle trap'],['P-trap','p trap'],['S-trap','s trap'],['Basin waste','basin waste'],['Air admittance valve','air admittance valve']],
  steps:['Put a bucket under the trap. Undo the slip nuts and remove the trap.','Empty the trap, clean it, and check the washers and the seal.','Check the trap seal depth: it must keep a water seal that is deep enough (check the standard for the seal depth of each trap type).','Re-fit the trap with the nuts hand-tight plus a quarter turn.','Run the tap and check for leaks and a smell. Fill the basin and let it empty to test for gurgling.','If the trap loses its seal after other fixtures empty, find the venting problem: waste too long, too flat, wrong size, or no vent.','If the pipe through the wall is open, seal it with a rubber cap or sealant.','Advise the customer on keeping seldom-used drains topped up.'],
  sans:['SANS 10252-2: each fixture trap must keep a water seal; check the seal depth, the waste size and the maximum trap-to-vent distance in the current edition.','A trap that is more than the permitted distance from a vent is a common reason for siphonage.']}},

{id:'sewer-smell-dry-trap',cat:'drainage,emergency',title:'Sewer smell in the house or yard',kw:'sewer smell stink rotten egg riool reuk gas hydrogen sulphide floor drain dry trap gully manhole vent pipe septic smell outside inside',sym:'whole house smells of sewer; smell from the floor drain; smell near the bathroom; smell outside near the manhole',sum:'Track down the source of a sewer smell',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Where is the smell strongest?',opts:[['One fixture (basin, bath, shower)','r_fix'],['A floor drain or gully','r_floor'],['Outside near a manhole or the vent pipe','r_out'],['Everywhere, and the toilet gurgles','r_blocked']]},
  r_fix:{res:1,cause:'A dry or siphoned trap at that fixture',do:['See Smell from a basin, bath or shower waste (trap).'],next:'repair'},
  r_floor:{res:1,cause:'A dry floor trap or gully with no water seal',do:['Pour water into the drain until the seal fills.','Add a little oil on top to slow evaporation.','Fit a trap primer where the floor drain is seldom used (maker/municipality).'],parts:[['Gully','gully']],next:'repair'},
  r_out:{res:1,cause:'A vent pipe discharges close to windows, or a manhole cover leaks gas',do:['Check the vent pipe outlet is above the roof and away from windows.','Check manhole covers seal.','If the smell is strong, the drain may be partly blocked or the sewer overloaded: tell the municipality.'],call:'municipality',next:'repair'},
  r_blocked:{res:1,cause:'Blocked or partly blocked main drain, pushing gas back into the traps',do:['See Blocked sewer or manhole.'],call:'plumber'}}},
 repair:{warn:[HYG_WARN,'Sewer gas contains hydrogen sulphide. You stop smelling it at high concentrations, so do not trust your nose. Never enter manholes or confined spaces.'],tools:['Bucket','Gloves','Torch','Drain rods (if needed)','Smoke machine or peppermint (optional)'],parts:[['Gully','gully'],['Rodding eye','rodding eye'],['Air admittance valve','air admittance valve'],['Cap and seal','pvc cement']],
  steps:['Ask when the smell started and whether a particular fixture or weather is involved.','Check each trap in the house: run water for a minute and check the seal holds.','Check floor drains and gullies for a dry seal, and refill them.','Check the pipe through the wall behind each fixture for open ends and unsealed gaps.','Look at the vent pipes on the roof: they should be open, unblocked, and not too near windows.','Check the manhole covers, rodding eye caps and inspection covers for tight seals.','If it is only after rain or at night, look for stormwater or ground-water entering a sewer joint or a collapsed pipe.','If all fixtures are slow or gurgle, treat it as a blocked main drain.','Refill and test again after an hour. Report to the customer what you found, with photos.'],
  sans:['SANS 10252-2: traps, venting and access. Check the current edition for vent termination heights and distances to openings.']}},

{id:'blocked-basin-bath-shower',cat:'drainage,bath,kitchen',title:'Blocked basin, bath, shower or sink',kw:'blocked basin bath shower sink kitchen drain slow draining clogged hair grease plunger auger snake trap cleaning verstop wasbak bad stort gootsteen stadig',sym:'water drains slowly; basin full of water; bath will not drain; sink blocked; gurgling noise',sum:'Clear a blocked fixture from the plug hole or the trap',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Is it only this fixture, or do other fixtures drain slowly too?',opts:[['Only this one','q2'],['Several fixtures or the toilet gurgles','r_main']]},
  q2:{q:'What is blocking it likely to be?',opts:[['Hair and soap (bathroom)','r_hair'],['Grease and food (kitchen)','r_grease'],['Something fell in','r_object']]},
  r_hair:{res:1,cause:'Hair and soap scum in the waste or trap',do:['Remove the strainer and pull out the hair.','Use a drain snake or a bent wire hook.','Unscrew the trap and clean it. Avoid strong chemicals on old or plastic pipes.'],parts:[['Drain auger','auger'],['Plunger','plunger'],['Bottle trap','bottle trap']],next:'repair'},
  r_grease:{res:1,cause:'Grease and food waste hardened in the trap and pipe',do:['Remove the trap and clear it. Hot water softens grease; flush with it.','Auger the pipe.','Advise the customer: no cooking oil down the sink; use a strainer.'],parts:[['Sink trap','sink trap'],['Drain auger','auger']],next:'repair'},
  r_object:{res:1,cause:'A foreign object in the trap or waste',do:['Remove the trap and look in it.','Use a retrieval tool or a flexible auger.'],parts:[['Drain auger','auger']],next:'repair'},
  r_main:{res:1,cause:'Blocked shared drain',do:['See Blocked sewer or manhole.'],call:'plumber'}}},
 repair:{warn:[HYG_WARN,'Do not mix drain chemicals; they can release dangerous gas or burn skin. Never use chemicals before using a plunger or a snake.'],tools:['Plunger','Drain auger or snake','Bucket','Gloves and glasses','Spanner or pliers','Torch','Old towels'],parts:[['Plunger','plunger'],['Drain auger','auger'],['Bottle trap','bottle trap'],['Sink trap','sink trap'],['Bath trap','bath trap'],['Shower waste','shower waste']],
  steps:['Protect the floor with towels and set a bucket under the trap.','Remove the strainer or pop-up and clean it.','Seal the overflow with a wet cloth and use the plunger on the plug hole with some water over the cup.','If the plunger fails, unscrew the trap and empty it into the bucket. Clean the trap.','Pass a snake or drain auger through the waste pipe until the blockage clears.','Re-fit the trap with its washers. Run hot water and check the flow and leaks.','Advise the customer on strainers and hair catchers, and how to avoid grease and wipes.','If other fixtures are slow too, check the main drain.']}},

{id:'blocked-sewer-manhole',cat:'drainage,emergency',title:'Blocked sewer line or full manhole',kw:'blocked sewer main drain manhole overflowing inspection chamber rodding jetting toilet gurgling backing up riool verstop mangat oorloop tree roots sewer line',sym:'manhole full of sewage; toilets will not flush and gurgle; sewage coming up the shower; sewage overflowing outside',sum:'Find the blockage, clear it and prevent a repeat',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Where do you see the sewage?',opts:[['Inside the house (shower or floor drain)','r_in'],['Outside at a manhole','q2'],['Only slow draining, toilets gurgle','r_slow']]},
  q2:{q:'Open the next manhole downstream (only if it is safe). Is it also full?',hint:'Never climb into a manhole.',opts:[['Yes, full','r_muni'],['No, it is empty or flowing','r_ours']]},
  r_in:{res:1,cause:'Blocked main line backing up into the lowest fixture',do:['Stop using all water in the house.','Find and open the rodding eye or the manhole nearest the house to see where it is full.','Clear the line with drain rods or a jetter.'],call:'plumber',next:'repair'},
  r_slow:{res:1,cause:'Partly blocked line: roots, scale, grease, nappies or wipes',do:['Rod or jet the line from the manhole downstream.','Camera the pipe if it keeps blocking.'],next:'repair'},
  r_muni:{res:1,cause:'The municipal sewer downstream is blocked',do:['Take photos and report to the municipality water and sanitation department with the address and the manhole position.','Stop using water until it is cleared.'],call:'municipality'},
  r_ours:{res:1,cause:'Blockage on your property between this manhole and the next',do:['Rod from the full manhole toward the empty one.','Clear it, then flush with water to prove the line.'],next:'repair'}}},
 repair:{warn:[HYG_WARN,'Never enter a manhole or inspection chamber. Gas can kill in seconds. Put out cones and cover the manhole when you leave. Keep children and pets away from sewage.'],tools:['Drain rods with a plunger and a corkscrew head','Manhole lifting key','Hose','Gloves, glasses, gumboots','Disinfectant','Cones and tape','Torch'],parts:[['Drain rods','drain rods'],['Rodding eye','rodding eye'],['Drain auger','auger'],['Manhole','manhole'],['Plunger','plunger']],
  steps:['Put out cones. Wear gloves, glasses and boots. Do not use any open flame or smoke near sewers.','Lift the nearest manhole cover or rodding eye cap and look from above only. Find the full chamber and the empty one.','Rod from the last empty chamber toward the full one or work from the clear side so debris flows away.','Assemble the rods with a head suited to the blockage (plunger for soft, corkscrew for hard) and push in a straight line without turning the rods anti-clockwise (they may unscrew).','When you feel the blockage give, push and pull a few times to break it up, then flush with water to prove the flow.','Check the line downstream: run a hose to carry the debris away.','Disinfect the area and clean your tools.','If it blocks again, use a camera to look for roots, a collapsed joint or a belly, and quote the repair. Trees near the line are a common cause.','Give the customer advice: no wipes, nappies, fat or sanitary products in the drain.']}},

{id:'rodding-jetting',cat:'drainage',title:'Rodding and jetting a drain',kw:'rodding rods jetting high pressure jetter drain cleaning sewer clean roots descale camera inspect rodding eye drain rods jetter spuit',sym:'clear a drain with rods; jet a sewer; clean a main line; roots in the drain',sum:'How to rod and jet a drain safely and what to check',
 repair:{head:'Checklist for drain cleaning',warn:[HYG_WARN,'A pressure jetter can injure skin and drive water through a damaged pipe. Never put your hand or foot near the nozzle. Use only the nozzle and pressure that suit the pipe.'],tools:['Drain rods and heads','Jetter (hired or owned)','Hose and water supply','Manhole key','Cones','Gloves, boots, glasses','Disinfectant','Camera'],parts:[['Drain rods','drain rods'],['Rodding eye','rodding eye'],['Auger','auger']],
  steps:['Find the access points: rodding eyes, manholes and inspection chambers. Mark them.','Check the pipe material and age: old clay, cast iron or fibre-cement pipes are more fragile.','Put out cones and wear PPE. Cover the open manhole when you leave it.','Rod first for a soft blockage; use a jetter for grease, scale and roots.','Feed the rods or hose in from the downstream side so debris travels away.','Pull the jetter back slowly while it cuts, working back toward the access point.','Flush with clean water and check the line runs clear.','Camera if you can: look for roots, cracks, offsets, bellies and joints.','Record the result: photos, time and what was found.','Leave the manhole cover seated and disinfect the area.']}},

{id:'gully-clean-install',cat:'drainage,outdoor',title:'Gully trap clean-out or installation',kw:'gully trap yard gully clean install gulley outside drain smell blocked grid grating waste gully trap leaves silt kitchen waste riool put',sym:'gully blocked; gully smells; install a new gully; gully overflowing',sum:'Clean a blocked or smelly gully, or fit a new one',
 repair:{warn:[HYG_WARN],tools:['Bucket and scoop','Gloves, boots','Hose','Brush','Drain rods (short)','Spade','Cement and sand (for bedding)'],parts:[['Gully','gully'],['Gully grate','gulley grate'],['Rodding eye','rodding eye'],['Auger','auger']],
  steps:['Lift the grid. Scoop out the mud and leaves from the gully; wash with a hose.','Check the water seal: the trap must hold water. If there is no seal, the outlet may be cracked or the gully is not a trap type.','Clear the outlet pipe with a short auger or rods. Flush with water.','Check that stormwater does not run into a gully that is connected to the sewer. Stormwater must not enter the sewer.','To fit a new gully: dig a firm base, bed the gully on concrete, and fall the waste into it. Connect the outlet to the drain.','Set the top slightly below the paving so the water runs in. Replace the grid.','Test by running a hose, check for leaks and the seal.']}},

{id:'french-drain-slotted-pipe',cat:'drainage,outdoor',title:'French drain or subsoil drainage (slotted pipe)',kw:'french drain subsoil drain slotted pipe nextube drainex agricultural drain wet yard damp wall seepage geotextile gravel water table soakaway dreinering',sym:'damp wall outside; wet patch in the garden; water pools behind retaining wall; groundwater seepage; subsoil drain',sum:'Install a gravel-and-slotted-pipe drain to take groundwater away',
 install:{head:'Install checklist',warn:['Never connect subsoil or ground water to the sewer. It must go to the stormwater system or a safe disposal point agreed with the municipality.','Call before you dig for buried cables, pipes and gas lines.'],tools:['Spade and pick','Level and string line','Wheelbarrow','Tape measure'],parts:[['Slotted pipe / Nextube','nextube'],['Drainex','drainex'],['Slotted pipe','slotted pipe'],['Rodding eye','rodding eye'],['Elbows','hdpe elbow']],
  steps:['Find the water source and where the water should go (stormwater drain or a safe outlet on the property).','Plan the trench with a continuous fall toward the outlet. Agree the outlet with the municipality if needed.','Dig the trench to the depth needed. Make the bottom smooth with a consistent fall.','Line the trench with geotextile (filter fabric) if available.','Lay a bed of clean stone (gravel), then the slotted pipe with the slots facing down or as the maker advises.','Cover with more stone, wrap the geotextile over the top, and backfill with soil.','Fit rodding access at corners and at the end so the drain can be cleaned.','Run water to test the outlet and check the fall.','Make good the garden and tell the customer the drain needs periodic checks.'],
  sans:['SANS 10400-R (stormwater disposal) and local by-laws govern where drainage water may go. Check the current standard and the municipality.']}},

{id:'stormwater-drainage',cat:'drainage,outdoor',title:'Stormwater drainage and gutters',kw:'stormwater storm water gutter downpipe rain water roof drain soakaway kerb inlet overflow flooding sump rainwater goods reenwater geut',sym:'water pools at the foot of the wall; gutter overflows; downpipe connects to the sewer; stormwater in the sewer',sum:'Basics of getting rainwater away without breaking the rules',
 repair:{warn:['Stormwater must never be connected to the sewer system. Check the municipal by-laws before connecting a downpipe or a drain.'],tools:['Ladder (secured)','Hose','Level','Spade','Gloves'],parts:[['Gutter','gutter'],['Downpipe','downpipe'],['Gully','gully'],['Rainwater leaf catcher','rainwater']],
  steps:['Look at where the roof water goes: gutters, downpipes, and the ground at the base.','Clean the gutters and the downpipe screens of leaves and silt.','Check gutter joints and brackets and the fall to the downpipe.','Make sure the downpipe discharges to a stormwater outlet or onto a surface that slopes away from the building.','Never connect a downpipe or yard drain to the sewer. If you find one, tell the customer and the municipality rule.','If water pools, level the ground so it falls away from the walls, or add a drain.','Test with a hose over the roof during the job.'],
  sans:['SANS 10400-R covers stormwater; check the current edition and the by-laws for where the water may be sent.']}},

{id:'venting-aav',cat:'drainage,install',title:'Venting and air admittance valves',kw:'vent venting stack vent aav air admittance valve durgo studor ventilation waste pipe siphon trap seal gurgling vent pipe roof slope belugting',sym:'gurgling pipes; trap loses its water; need a vent for a basin far from the stack; can I use an air admittance valve',sum:'When a waste needs a vent and what an AAV can do',
 repair:{head:'Venting checklist',tools:['Tape measure','Level','Pipe cutter','Camera'],parts:[['Air admittance valve','air admittance valve'],['Vent pipe','pvc pipe 50mm'],['Bottle trap','bottle trap']],
  steps:['Measure the length and fall of each waste from the trap to the stack or vent.','Check the maximum trap-to-vent distance for the waste size (the manual rule of thumb is about 6 m for a basin waste and about 10 m for larger fixtures: check the standard).','Look for signs of a vent problem: gurgling, suction on traps, slow draining, smell.','Make sure every stack has a ventilated top (open vent through the roof) unless the municipality allows a valve.','An air admittance valve (AAV) lets air in but not out. It may not be accepted by every municipality or for every situation: check the by-laws.','Fit an AAV where it is accessible, above the flood level of the highest fixture on that waste, and in a space with free air.','Do not use an AAV as the only vent on the entire system.','Test by running several fixtures at once and watch the traps.'],
  sans:['SANS 10252-2 covers venting. Check the current edition for permitted trap-to-vent lengths, the vent sizes and the rules for AAVs.']}},

{id:'fall-on-waste-pipes',cat:'drainage,install',title:'Fall (gradient) on waste and soil pipes',kw:'fall gradient slope waste pipe soil pipe 1:46 1:40 1:60 mm per metre drain fall calculator table 15 hellings val',sym:'what fall must a waste pipe have; how much slope for a drain; sewer fall',sum:'Standard minimum falls, how to measure them and what is not the standard',
 repair:{head:'Fall checklist',tools:['Spirit level','String line','Tape measure','Fall calculator (in the Plumbing Manual)','Camera'],parts:[['Spirit level','spirit level'],['Pipe clip','pipe clip'],['Drain rods','drain rods']],
  steps:['Use the pipe length and the fall ratio to find the drop. Drop in mm = length in mm divided by the ratio (for 1:46, a 1 m pipe drops about 21.7 mm).','SANS 10252-2 Table 15 gives minimum falls of 1:46 for waste branches and 1:40 for soil branches (guide only: check the table for each pipe size and fixture).','A steeper fall is not always better: very steep falls can leave solids behind.','Mark the fall on the wall with a string line before fixing the pipe, and set the level to check.','Support the pipe so it cannot sag; a sag holds water and can block.','Check the fall after fixing: pour water and watch it run away.','Record the fall in the job photos with a level on the pipe.','Site practice of 1:40 for 50 mm and 1:60 for 110 mm is NOT the standard. Do not quote it to customers or inspectors as the standard.'],
  sans:['SANS 10252-2, Table 15 (waste and soil pipe falls). Check the current edition for the ratio for each pipe.','Falls on drains underground follow the same standard and the drain size.']}},

{id:'frozen-pipes',cat:'leaks,emergency',title:'Frozen pipes',kw:'frozen pipes freeze frost ice burst cold winter highveld thaw lagging insulation pipes outside pyp bevrore ryp ysig',sym:'no water in winter morning; pipes frozen; tap gives no water after a frosty night; burst pipe after freeze',sum:'Thaw safely and stop them freezing again',
 repair:{warn:['Never use an open flame on pipes. Heat the pipe gradually. Open a tap so the steam and melted water can escape. A frozen pipe may already be split: expect a leak when it thaws.'],tools:['Hair dryer or warm cloths','Pipe lagging','Pipe cutter','Spanners','Bucket'],parts:[['Pipe lagging','lagging'],['Geyser blanket','geyser blanket'],['Pipe clip','pipe clip'],['Copper repair coupling','copper repair coupling']],
  steps:['Open the tap nearest the frozen section so water can flow as the ice melts. Close the main valve if you see a split pipe.','Heat the pipe slowly from the tap side toward the cold section using warm cloths, or a hair dryer. No open flame, no blow torch.','Watch for leaks as the ice melts. If a pipe has split, close the supply and repair or replace that section.','Check fittings, valves and the geyser safety valve for damage.','Fit pipe insulation (lagging) to exposed pipes: roof space, outside walls, garden taps and anywhere with draught.','Insulate the geyser, its pipes and the safety valve drain.','Advise the customer: in a very cold night, drip a tap and cover exposed taps. Shut off and drain irrigation and outside taps.','Check the roof tanks and the meter box are covered.']}},
{id:'join-copper-solder',cat:'leaks,install',title:'Joining copper pipe (capillary solder fittings)',kw:'copper solder soldering capillary joint flux torch lead free solder end feed solder ring bernzomatic cut deburr sweat copper pipe koper soldeer',sym:'how to solder copper; dry joint leaks; joint wont take solder; repair a copper pipe',sum:'Cut, clean, flux and solder a copper joint properly',
 repair:{head:'Soldering checklist',warn:['Hot work: keep a fire blanket and a wet cloth or water nearby. Protect timber, ceilings and plastic with a heat mat. Never solder a pipe that still has water in it. Use only lead-free solder on drinking-water pipes.'],tools:['Pipe cutter','Deburring tool','Wire wool or abrasive pad','Flux brush','Gas torch (Bernzomatic or similar)','Heat mat','Rag','Fire blanket'],parts:[['Copper pipe 22mm','copper pipe 22mm'],['Copper elbow 22mm','copper elbow 22mm'],['Copper tee 22mm','copper tee 22mm'],['Soldering flux','soldering flux'],['Torch','torch'],['Pipe cutter','pipe cutter']],
  steps:['Close the water and drain the pipe fully. Open a tap lower down so no water or steam is trapped in the joint.','Cut the copper square with a pipe cutter. Deburr inside and outside.','Clean the pipe end and the inside of the fitting until bright with an abrasive pad.','Brush a thin layer of flux on both surfaces. Push the fitting on and twist.','Heat the fitting (not the solder) evenly with the torch flame, moving it around the joint.','Touch the solder to the joint edge opposite the flame. When it melts and is drawn in, stop. Do not overheat the joint.','Let the joint cool without moving it. Wipe off flux residue with a damp cloth.','Test: open the water slowly and check each joint. Re-make dry joints; do not add solder on a wet joint.','Support the pipe with clips at the right spacing; see Pipe supports and sleeving.','Use the correct tube class for the job (check SANS 460 and the supplier).'],
  sans:['SANS 460 covers copper tubes (classes for wall thickness). Check the standard for the right class for each use.','SANS 10252-1: materials and joints must be suitable for potable water. Lead-free solder and flux are required for drinking water.']}},

{id:'join-pex-multilayer',cat:'leaks,install',title:'PEX and multilayer pipe (press, crimp, compression)',kw:'pex multilayer pexal alu pex crimp press fitting compression fitting calibrator reamer sleeve ring plastic pipe underfloor manifold pexman mepla pyp',sym:'how to join pex; multilayer pipe leaks at the fitting; pex crimp ring; repair pex pipe',sum:'Cut, prepare and join PEX or multilayer pipe with the right fitting',
 repair:{head:'PEX / multilayer checklist',warn:['Use only the fittings and tools made for the pipe brand. Mixing makes or tools can fail under pressure. Keep multilayer and PEX out of direct sunlight and away from hot flues.'],tools:['Pipe cutter (plastic)','Calibrator / reamer','Crimping or pressing tool','Bending spring or bender','Clips','Marker'],parts:[['Multilayer pipe','multilayer pipe'],['PEX pipe','pex'],['Crimping tool','crimping tool'],['Pipe clips','pipe clip'],['Speedfit','speedfit']],
  steps:['Select the pipe and the matching fittings (same brand and size).','Close and drain the line. Cut the pipe square with the pipe cutter.','Ream and calibrate the pipe end so the fitting seats fully (multilayer: remove burrs and re-round the pipe).','Slide the ring or nut on, push the pipe fully onto the fitting and check the depth mark.','Crimp or press with the correct tool and jaw size, or tighten the compression nut as the maker says.','Check the joint is square and the depth mark is at the edge of the ring.','Support pipes at the maker spacing with clips; allow for thermal movement (expansion) on long hot runs.','Pressure test before closing the walls (see Pressure testing in the manual).','Label hot and cold and keep hot pipes insulated.']}},

{id:'join-compression-pushfit-solvent',cat:'leaks,install',title:'Compression, push-fit and solvent-weld joints',kw:'compression fitting olive push fit pushfit speedfit solvent weld pvc cement primer glue joint push in coupling joint dichting koppeling gom',sym:'how to use a push fit joint; solvent weld joint failed; compression fitting leaking; pvc cement',sum:'Choosing and making mechanical and solvent joints correctly',
 repair:{head:'Joint checklist',warn:['PVC cement and primer: ventilate, no flames, keep away from skin and eyes. Let solvent joints cure before pressure testing (see the maker).'],tools:['Pipe cutter or saw','Deburring tool','Marker','Cloth','Brush for cement','Chamfer tool','Spanner'],parts:[['Compression coupling','compression coupling'],['Speedfit coupling','speedfit'],['Solvent cement','solvent weld'],['PVC cement','pvc cement'],['Pipe cutter','pipe cutter']],
  steps:['Choose the joint: compression (brass olive), push-fit (Speedfit and similar) or solvent weld (PVC). Use the type the pipe and the application allow.','Cut square, deburr and chamfer the pipe end. Wipe it clean.','Compression: slide the nut and olive on, insert the pipe fully, tighten the nut by hand then 1 to 1.5 turns with a spanner (check the maker).','Push-fit: mark the insertion depth and push the pipe to the mark. Use the support insert where the maker requires it. Check the grab ring is seated.','Solvent weld: dry-fit, mark the depth, clean, apply primer if needed, apply even cement, push and hold for the time the maker gives.','Keep the joint still while it sets; wipe off the excess.','Do not use solvent cement on materials that are not PVC; do not use PVC cement for hot water.','Test only after the cure time. Re-make any weeping joint.'],
  sans:['SANS 10252-1: joint types and materials for potable water. Check which joint is approved for hot water and for pressure.']}},

{id:'pipe-supports-sleeving',cat:'leaks,install',title:'Pipe supports, clips and sleeving',kw:'pipe supports clips spacing sleeve sleeving through wall expansion copper pex pvc brackets saddle clamp sag noise rubber lagging steunings spasie',sym:'how far apart should clips be; pipes rattle; pipe sagging; pipe through a wall needs sleeve',sum:'Support spacing rules of thumb and when to use sleeves',
 install:{head:'Install checklist',warn:['Do not nail or screw into walls before checking for hidden pipes and cables.'],tools:['Drill and bits','Spirit level','Tape measure','Clips and screws','Rubber sleeve or lagging'],parts:[['Pipe clip','pipe clip'],['Rawlplug','rawlplug'],['Sleeve','sleeve'],['Lagging','lagging']],
  steps:['Use the spacing from the manufacturer or the standard. As typical trade values (not from the standard): uPVC up to 50 mm about 0.6 m horizontal and 1.5 m vertical; copper 15 mm about 1.2 m horizontal and 1.8 m vertical; copper 22 to 28 mm about 1.8 m horizontal and 2.4 m vertical. Check the standard.','Support near each fitting, valve and change of direction.','Allow for expansion: copper moves about 0.017 mm per metre per degree of temperature rise. Use loops or sliding clips on long hot runs.','Use rubber-lined clips or lagging so metal does not rattle or touch dissimilar metal.','Sleeve pipes passing through walls and slabs, so they can move without damage and are easy to replace. Seal the gap against fire, damp and noise as needed.','Do not bury unprotected pipes in concrete or plaster; use a sleeve or lagging and keep joints accessible.','Check the pipe is straight and falls correctly (drains) before fixing the last clips.'],
  sans:['SANS 10252-1 and 10252-2 give support requirements. Spacing here is a guide only: check the current edition.']}},

{id:'pipe-sizing-flow',cat:'pressure,install',title:'Pipe sizing and flow checks',kw:'pipe size sizing flow rate litres per minute bucket test pressure drop 15mm 22mm 28mm diameter supply main velocity pyp grootte vloei',sym:'what size pipe do I need; flow is poor; measure the flow; 15mm too small',sum:'Quick checks for supply pipe size, flow and pressure',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What do you want to find out?',opts:[['How much flow I have now','r_flow'],['What size to install for a new house','r_size'],['Flow is poor even though the pressure is fine','r_poor']]},
  r_flow:{res:1,cause:'Measure it with a bucket and a timer',do:['Open a tap fully and fill a 10 L bucket. Note the time.','Flow in litres per minute = 10 divided by the seconds, times 60.','Compare with the fixture needs in SANS 10252-1 (check the table).','Measure pressure at the same point with a gauge.'],parts:[['Pressure gauge','pressure gauge']]},
  r_size:{res:1,cause:'Pipe sizing follows the standard tables (fixture units and length)',do:['Use the pipe sizing method in SANS 10252-1: fixtures, flow rate, length and pressure available.','Typical trade sizes: 22 mm main to a house, 15 mm to fixtures; geyser feeds usually 22 mm. These are guides, not the standard.','Check the municipal supply pressure and the meter size.','Keep runs short and avoid unnecessary bends and restrictions.'],parts:[['Copper pipe 22mm','copper pipe 22mm']]},
  r_poor:{res:1,cause:'Restriction: partly closed valve, blocked strainer, scaled pipe, undersized pipe or too many bends',do:['Check each isolating valve is fully open.','Check strainers, filters and the meter strainer.','Compare pressure at the meter with the pressure at the fixture; a big drop means a restriction.','Replace undersized or corroded pipe.'],parts:[['Strainer','strainer'],['Ball valve 22mm','ball valve 22mm']]}}},
 repair:{head:'Flow check steps',tools:['10 L bucket','Stopwatch (phone)','Pressure gauge','Tape measure'],parts:[['Pressure gauge','pressure gauge'],['Strainer','strainer']],
  steps:['Close all other taps. Read the static pressure at the tap or outside bib with a gauge.','Open the tap fully and fill a 10 L bucket. Time it. Flow in L/min = 600 divided by the seconds.','Read the pressure again with the tap open (running pressure). A big drop between static and running pressure means a restriction or an undersized pipe.','Check isolating valves, strainers and filters for restrictions.','Compare against the fixture flow needs and the sizing tables in SANS 10252-1 (check the standard).','Where you must upsize, replace the restricted section and shorten the run; avoid unnecessary bends and fittings.','Record the numbers on the job card.']}},

{id:'hidden-leak-hunt',cat:'leaks',title:'Hidden leak detection',kw:'hidden leak detection find leak meter test damp wall slab leak pressure test stethoscope acoustic leak listening water bill high underground leak verborge lek meter',sym:'water bill high; meter running with taps off; wet patch in the garden; damp wall with no visible leak',sum:'Step-by-step method to find and prove a hidden leak',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Close all taps and appliances. Does the meter dial still turn?',opts:[['Yes','q2'],['No','r_none']]},
  q2:{q:'Close the main stopcock at the house. Does the meter still turn?',opts:[['Yes (leak before the house stopcock)','r_before'],['No (leak is inside)','q3']]},
  q3:{q:'Does the toilet cistern pass water into the pan? (put a few drops of food colour in the cistern)',opts:[['Yes','r_toilet'],['No','q4']]},
  q4:{q:'Is the geyser safety valve or the garden irrigation dripping?',opts:[['Yes','r_geyser'],['No','r_hidden']]},
  r_none:{res:1,cause:'No continuous leak at this moment',do:['The meter can pause between pulses; wait 10 minutes and look again.','Check for intermittent leaks: a cistern that fills now and then, or a geyser valve that opens when it heats.'],next:'repair'},
  r_before:{res:1,cause:'A leak on the supply pipe between the meter and the house, or the meter itself',do:['Look for wet ground or green patches on the line.','Isolate sections by closing valves.','Dig and repair the leak. The meter and pipe before it belong to the municipality.'],call:'municipality',next:'repair'},
  r_toilet:{res:1,cause:'A leaking flush valve',do:['See Running toilet and Toilet flush valve.'],parts:[['Flush valve','flush valve']]},
  r_geyser:{res:1,cause:'Dripping safety valve, irrigation valve or tap',do:['See Geyser dripping and Irrigation leak.']},
  r_hidden:{res:1,cause:'A leak in a concealed pipe, in a wall, floor or ceiling',do:['Isolate sections of the house with valves and watch the meter.','Pressure test the pipes (see Pressure testing).','Use a listening device (stethoscope) or a thermal camera when you have one.','Open the floor or wall minimally and repair the pipe.'],next:'repair'}}},
 repair:{warn:['Opening walls and floors: check for electric cables and other pipes.'],tools:['Torch','Phone camera','Pressure gauge and test pump','Stethoscope or listening rod','Cap-off fittings','Marker','Notepad'],parts:[['Pressure gauge','pressure gauge'],['Test plug','test plug'],['Copper repair coupling','copper repair coupling'],['Stop tap','stop tap']],
  steps:['Read the meter at the start and end. Note the dial and the digits. Take a photo.','Make sure all taps, the geyser and appliances are off. Check if the meter moves.','Close the main stopcock and read the pressure at an outside tap. If the meter still turns, the leak is before the stopcock.','Test the cistern with food colouring and check the geyser safety valve drain, irrigation and pool top-up.','Isolate sections: close valves for the bathroom, kitchen, geyser and garden one at a time and watch the meter.','Pressure test the suspect branch: cap it, pump up to the test pressure and watch the gauge for at least 15 minutes (test pressure per the standard).','Listen along the pipe with a stethoscope or rod; leaks hiss or drip loudest near the break.','Open a small inspection hole at the suspected spot. Repair and replace the damaged section.','Re-test and record the final meter reading, with photos.']}},

{id:'air-in-pipes',cat:'pressure,leaks',title:'Air in pipes (spitting taps)',kw:'air in pipes spitting taps sputtering airlock air lock noise water supply cut bleed vacuum geyser drained lug in pype spuug kraan',sym:'taps spit and splutter; air in the water lines; no flow after water cut; airlock in geyser lines',sum:'Get trapped air out and find where it enters',
 repair:{tools:['Hose','Bucket','Wrench'],parts:[['Air valve','air valve'],['Ball valve 22mm','ball valve 22mm']],
  steps:['Open the lowest tap and the highest tap together; run water until the flow is steady with no air.','Close the main valve, open all taps, then reopen the main slowly so the air is pushed out of the taps.','For a geyser: open a hot tap close by before filling it and keep it open until water runs without air.','If air keeps appearing, look for the source: a leaking suction joint on a pump or borehole line, a low-level tank, a crack in a pipe on the suction side, or a dropping water level.','Check the float valve and the municipal supply; air is common after the municipality has worked on the main.','For a high point that collects air, fit an air release valve (accessible).','Check that the isolating valves open fully and nothing restricts the line.']}},

{id:'prv-install',cat:'pressure,install',title:'Fit a pressure control valve (PCV / PRV)',kw:'pressure reducing valve pressure control valve prv pcv high pressure set pressure 400 kpa 300 kpa regulator install main supply kpa drukklep',sym:'water pressure is too high; taps bang; geyser valve leaking; install a PRV',sum:'Install and set a pressure control valve on the supply',
 install:{head:'Install checklist',warn:['Check the supply pressure with a gauge first. Fit the valve with unions and isolating valves on both sides so it can be serviced.'],tools:['Pressure gauge','Spanners','Pipe cutter','PTFE tape','Level'],parts:[['Pressure control valve','pcv'],['Isolating valve','ball valve 22mm'],['Union','union 22mm'],['Pressure gauge','pressure gauge'],['Strainer','strainer']],
  steps:['Measure the static pressure at an outside tap with a gauge. Note it.','Choose the valve size to match the supply pipe, and the set-point pressure range suited to the house (many houses are set around 300 to 400 kPa; check the fixtures and the standard).','Fit it in the main supply after the isolating valve, with a strainer upstream and an isolating valve on each side.','Mind the flow direction arrow on the body.','Fit a pressure gauge point downstream to set and check the pressure.','Open the system slowly and bleed air.','Set the pressure with the adjusting screw; lock it.','Check the hot water system: the safety valve should no longer open and taps should be quieter.','Advise the customer that the valve needs a check every few years.'],
  sans:['SANS 10252-1: the maximum static pressure at fixtures and the requirement for a pressure-reducing valve where the supply pressure is high. Check the current standard for the numbers.']}},

{id:'prv-noisy',cat:'pressure,leaks',title:'Pressure valve noisy or not holding',kw:'pressure control valve noisy singing hissing humming not reducing creeping pressure pcv prv failed diaphragm strainer blocked geyser valve opens lawaai',sym:'valve screams; water pressure still high after the valve; downstream pressure creeps up; pcv hum',sum:'Why a PCV hisses, hums or lets pressure creep',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is it doing?',opts:[['Hissing or humming when water flows','r_noise'],['Downstream pressure rises when no water flows (creep)','r_creep'],['No pressure at all downstream','r_block'],['Leaks from the body','r_leak']]},
  r_noise:{res:1,cause:'Valve oversized, set too low, worn parts or a blocked strainer',do:['Check the strainer in front of the valve and clean it.','Check the valve size against the flow and the maker advice.','Replace worn internals or the valve.'],parts:[['Pressure control valve','pcv'],['Strainer','strainer']]},
  r_creep:{res:1,cause:'Dirt or wear on the seat so it does not shut off fully',do:['Close the isolating valves, remove the cartridge and clean the seat.','Replace the cartridge or the valve.','Fit an expansion vessel or a thermal expansion arrangement if the pressure rise is caused by a closed hot-water system (check the maker).'],parts:[['Pressure control valve','pcv']]},
  r_block:{res:1,cause:'Blocked strainer or closed valve',do:['Open the isolating valves, clean the strainer.','Check the setting.'],parts:[['Strainer','strainer']]},
  r_leak:{res:1,cause:'Worn seal or cracked body',do:['Replace the seals or the valve.'],parts:[['Pressure control valve','pcv']]}}},
 repair:{head:'PCV service steps',warn:['Close the isolating valves and release the pressure before opening the valve.'],tools:['Spanners','Pressure gauge','Brush','Replacement cartridge or valve'],parts:[['Pressure control valve','pcv'],['Strainer','strainer'],['Pressure gauge','pressure gauge']],
  steps:['Measure the pressure before and after the valve with the gauge, with the taps closed and then open.','Close the isolating valves and open a tap to relieve pressure.','Remove and clean the strainer ahead of the valve.','Open the valve and remove the cartridge. Clean the seat and check the seal and diaphragm for wear.','Replace the cartridge or the valve if it is worn, scored or perished.','Refit, open the isolating valves slowly and set the pressure again.','Check that the downstream pressure holds steady when no water is used.']}},

{id:'borehole-pump-setup',cat:'outdoor,pressure',title:'Borehole pump and pressure tank checks',kw:'borehole pump submersible jet pump pressure tank bladder pre-charge pressure switch cut in cut out cycling short cycling dry run protection boorgat pomp druktenk skakelaar',sym:'borehole pump cycles on and off; pressure tank waterlogged; pump runs but no pressure; borehole water sandy',sum:'Checks for a borehole pump set with a pressure tank',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is the pump doing?',opts:[['Switches on and off every few seconds','r_cycle'],['Runs all the time, low pressure','r_low'],['Does not run','r_dead'],['Sand or air in the water','r_sand']]},
  r_cycle:{res:1,cause:'A waterlogged or low-charge pressure tank',do:['Switch off the pump and drain the tank to zero pressure.','Check the air (pre-charge) pressure at the tank valve: it should be about 20 kPa below the pump cut-in pressure (check the maker).','Pump the tank up to the correct charge and refill.','Replace a failed bladder.'],call:'plumber'},
  r_low:{res:1,cause:'Worn pump, a leak, a low water level or a blocked inlet screen',do:['Check for leaks on the delivery line.','Check the water level in the borehole.','Check the pump rating against the head and flow needed.','A pump specialist can pull the pump.'],call:'plumber'},
  r_dead:{res:1,cause:'No power, tripped overload, failed pressure switch, or a dry-run protection trip',do:['Electrician checks the supply and the controller.','Check the pressure switch contacts and setting.','If the borehole is dry, wait for it to recover and fix the cause.'],call:'electrician'},
  r_sand:{res:1,cause:'Pump screen damaged or the borehole is collapsing',do:['Stop the pump.','A borehole contractor should inspect it.','Fit a filter on the delivery line.'],parts:[['Water filter','water filter']]}}},
 install:{warn:[ELEC_WARN,'Do not connect a borehole to the municipal water supply. Keep it separate and use backflow protection where there is any cross-connection. Check the borehole registration and the municipal rules.'],tools:['Pressure gauge','Spanners','Pipe cutter','PTFE tape','Multimeter (electrician)'],parts:[['Pressure gauge','pressure gauge'],['Non-return valve','non return valve'],['Ball valve 22mm','ball valve 22mm'],['Tank','tank'],['Water filter','water filter']],
  steps:['Check borehole rules: registration and the municipal conditions. Test the water quality if it will be used for drinking (SANS 241 is the drinking-water quality standard).','Plan the position of the tank, pump, pressure switch and filters. Keep everything under cover and accessible.','Fit a non-return valve and isolating valves on the delivery line.','Fit a pressure tank and set its pre-charge to about 20 kPa under the cut-in pressure (check the maker).','Fit the pressure switch and gauge; set the cut-in and cut-out pressures as the pump maker says.','The electrician makes the supply, with an overload and earth leakage protection and dry-run protection.','Flush the line to clear sand before connecting fixtures. Fit a filter.','Test run: watch the cut-in and cut-out, and check for leaks, cycling and vibration.','Explain to the customer: never run the pump dry, check the tank pressure every year.'],
  sans:['SANS 241 covers drinking-water quality; water from a borehole may need treatment and testing.','SANS 10252-1: avoid cross-connection with municipal water; backflow protection where needed.']}},

{id:'booster-pump-troubleshoot',cat:'pressure',title:'Booster pump troubleshooting',kw:'booster pump shurflo grundfos pressure pump surge cycling noisy switches on and off no pressure flow switch pressure switch tank water pomp druk verhoger',sym:'booster pump keeps starting; pump noisy; pressure drops when pump runs; pump will not start',sum:'Quick check of a house booster pump',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is the problem?',opts:[['Pump will not start','r_dead'],['Starts and stops quickly','r_cycle'],['Pump runs, little pressure','r_low'],['Noisy','r_noise']]},
  r_dead:{res:1,cause:'No power, tripped overload, or a failed switch',do:['Check the plug, breaker and fuse (electrician).','Check the water supply to the pump: tank level, closed valve.'],call:'electrician'},
  r_cycle:{res:1,cause:'Leak downstream, waterlogged tank or a failed non-return valve',do:['Check for leaks (see Meter running).','Check the tank pre-charge.','Replace the non-return valve.'],parts:[['Non-return valve','non return valve']]},
  r_low:{res:1,cause:'Air in the suction line, blocked inlet filter or worn pump',do:['Check the inlet filter and suction joints for air leaks.','Prime the pump.','Check the tank has water.'],parts:[['Strainer','strainer'],['Booster pump','booster pump']]},
  r_noise:{res:1,cause:'Cavitation or loose mounting',do:['Check the suction pipe size and inlet; fit rubber mounts or flexible hoses.'],parts:[['Flexi hose','flexi hose']]}}},
 repair:{head:'Pump checks',warn:[ELEC_WARN],tools:['Pressure gauge','Spanners','Multimeter (electrician)','PTFE tape'],parts:[['Non-return valve','non return valve'],['Booster pump','booster pump'],['Flexi hose','flexi hose']],
  steps:['Check the water supply to the pump: tank has water, inlet valve open, inlet filter clean.','Switch off, open the pump and prime it as the maker says. Never run a pump dry.','Check all suction-side joints for air leaks.','Check the pressure tank pre-charge (power off, tank empty): about 20 kPa under the cut-in pressure (check the maker).','Check the non-return valve and the pressure switch.','Run the pump and watch the pressure gauge: cut-in, cut-out and whether it holds when no water is used.','Fit flexible hoses and rubber feet to reduce noise.','Electrical faults go to an electrician.']}},

{id:'dishwasher-washing-machine',cat:'kitchen',title:'Dishwasher and washing machine connection',kw:'dishwasher washing machine washer connection standpipe waste hose tap 3/4 hose connector double check valve install point inlet drain hose machine koppel wasmasjien skottelgoed',sym:'connect a washing machine; install a dishwasher; machine leaks; waste hose siphons',sum:'Connect the supply, waste and valves for a washing machine or dishwasher',
 install:{head:'Install checklist',warn:['Turn off the water and the power before moving a machine. Use an isolating tap that is easy to reach.'],tools:['Spanners','PTFE tape','Pipe cutter','Spirit level','Hose clips'],parts:[['Washing machine tap','washing machine tap'],['Standpipe','standpipe'],['Dishwasher / washing machine hose','flexi hose'],['Trap','sink trap'],['Y piece','y piece']],
  steps:['Check the machine manual for the supply pressure range and the hose type.','Fit an isolating tap (washing machine tap) on the cold supply near the machine. Fit a filter washer.','Connect the inlet hose hand-tight plus a quarter turn.','Waste: connect to a standpipe with an air gap, or a trap with a spigot. The waste hose must loop high (follow the manual) so it cannot siphon.','Check the standpipe height and diameter are correct for the machine pump.','Open the tap and check for leaks. Run a test cycle and look for water at the waste.','Level the machine. Check the vibration and the hoses are not kinked.','Label the isolating tap and show the customer.'],
  sans:['SANS 10252-1: backflow protection and air gap at appliance waste. Check the maker and the standard for double check valves and standpipe sizes.']}},

{id:'water-filter-install',cat:'kitchen,install',title:'Water filter installation',kw:'water filter install under sink inline filter whole house cartridge housing viscosity sediment carbon uv reverse osmosis filter housing bracket filter replace cartridge',sym:'fit a water filter; change a filter cartridge; filter reduces pressure; filter leaks',sum:'Install a point-of-use or whole-house filter and change cartridges',
 install:{head:'Install checklist',tools:['Pipe cutter','Spanners','Filter wrench','PTFE tape','Drill','Bucket'],parts:[['Filter housing','filter housing'],['Filter cartridge','filter cartridge'],['Inline filter','inline filter'],['Isolating valve','ball valve 22mm'],['Flexi hose','flexi hose']],
  steps:['Decide where it goes: whole house on the main, or under the sink for drinking water. Check the flow rate and the pressure drop.','Fit an isolating valve before the filter and, for whole house, a bypass.','Mount the bracket and housing with space below to unscrew it. Mind the flow direction arrow.','Connect inlet and outlet with unions so the unit can be removed.','Open the valve slowly and bleed air with the red release button or loosening the bleed screw.','Check for leaks and flush the cartridge as the maker says.','Write the install date on the housing and tell the customer when to change cartridges.','Use cartridges suited to the water problem: sediment, carbon (taste and chlorine), etc.']}},

{id:'irrigation-leak-valve',cat:'outdoor',title:'Irrigation leak or valve problem',kw:'irrigation sprinkler leak valve solenoid garden drip line controller timer backflow pop up sprinkler head hunter rainbird sproeier besproeiing',sym:'sprinkler valve does not close; wet patch in the garden; low pressure in irrigation; sprinkler head leaks',sum:'Find a leaking or stuck irrigation valve or line',
 diagnose:{start:'q1',nodes:{
  q1:{q:'What is wrong?',opts:[['A zone will not switch off','r_valve'],['Wet patch or water bubbling up','r_leak'],['Weak spray from sprinklers','r_flow'],['Zone does not switch on','r_sol']]},
  r_valve:{res:1,cause:'Dirt in the valve diaphragm or a worn diaphragm',do:['Turn off the supply, open the valve and clean the diaphragm and solenoid port.','Replace the diaphragm or the valve.'],parts:[['Isolating valve','ball valve 22mm'],['Gate valve','gate valve']]},
  r_leak:{res:1,cause:'Broken pipe or fitting under the lawn',do:['Switch off the zone, dig to find the leak and replace the pipe or fitting.','Use solvent weld or the right irrigation fittings.'],parts:[['HDPE elbow','hdpe elbow'],['Hose union','hose union']]},
  r_flow:{res:1,cause:'Clogged sprinkler nozzles, filter or low supply pressure',do:['Clean nozzles and the filter.','Check that no leak is dropping the pressure.'],parts:[['Filter','inline filter']]},
  r_sol:{res:1,cause:'Failed solenoid, wiring or controller',do:['Test the controller and solenoid with a meter (low voltage) or swap the solenoid.'],parts:[['Isolating valve','ball valve 22mm']]}}},
 repair:{warn:['Switch off the controller and the supply before digging. Check for buried cables. Irrigation connected to the municipal supply needs backflow protection.'],tools:['Spade','Pipe cutter','Spanners','Fittings','Multimeter'],parts:[['Hose union','hose union'],['Hose bib','hose bib'],['HDPE elbow','hdpe elbow'],['Vacuum breaker','vacuum breaker']],
  steps:['Switch off the controller and close the main irrigation valve.','Walk the zones with the water on and mark wet or soft spots.','Dig carefully around the leak, expose the pipe and cut out the damaged section.','Fit a coupling or repair fittings and bed the pipe in sand; flush before closing.','Check the backflow device (vacuum breaker) is fitted where required and works.','Test each zone and check the pressure at the farthest sprinkler.','Backfill and reinstate the lawn.']}},

{id:'rainwater-harvesting',cat:'outdoor,install',title:'Rainwater harvesting tie-in',kw:'rainwater harvesting tank jojo gutter downpipe first flush leaf catcher pump overflow top up municipal air gap non potable garden toilet reenwater tenk',sym:'connect a rainwater tank; use rainwater for the toilet; tank top up from municipal; rainwater overflow',sum:'Basics of a safe rainwater tank connection',
 install:{head:'Install checklist',warn:['Rainwater is not safe to drink unless treated. Never connect a rainwater system to the potable supply without a proper air gap or approved backflow device. Label all non-potable pipes.'],tools:['Spirit level','Hacksaw','Drill','Pipe cutter','Solvent cement'],parts:[['Rain water tank','rain water tank'],['Leaf catcher','rainwater'],['Tank float valve','tank float'],['Pump','booster pump'],['Gutter','gutter'],['Downpipe','downpipe']],
  steps:['Plan the catchment (roof), the tank position on a firm level base, the overflow route and the use of the water.','Fit gutters and downpipes with leaf catchers or a first-flush diverter.','Install the tank on a compacted base. Plan the overflow to a stormwater outlet, not the sewer.','Fit a screened inlet and a vermin-proof overflow.','If the tank is topped up with municipal water, use an air gap above the tank high-water level. A direct connection is not allowed without backflow protection.','Label all pipes that carry rainwater as non-potable. Colour-code if your municipality requires it.','Fit a pump and filter for garden or toilet supply as needed.','Test the overflow and the pump; check for leaks.'],
  sans:['SANS 10252-1: separation of potable and non-potable water and backflow protection. Check by-laws.','SANS 10400-R: stormwater and overflow. Check the current edition.']}},

{id:'boundary-stopcock-isolator',cat:'leaks,install',title:'Stopcock, isolator and boundary valve replacement',kw:'stopcock stop cock stop tap isolator isolating valve boundary valve meter box gate valve ball valve replace main valve leaking spindle seized sluitkraan hoofkraan',sym:'main valve leaks; stopcock will not close; replace isolator; meter box valve',sum:'Replace a house stopcock or isolator safely',
 repair:{warn:['The municipal meter and the valve next to it belong to the municipality. Do not tamper with it. If it will not close, get the municipality to close the supply at the main.','If the main stopcock cannot be closed, the supply has to be closed upstream.'],tools:['Spanners','Pipe cutter','PTFE tape','Bucket','Towels','Hacksaw'],parts:[['Stop tap','stop tap'],['Gate valve','gate valve'],['Ball valve 22mm','ball valve 22mm'],['Meter box','meter box'],['Union','union 22mm']],
  steps:['Close the water at the municipal valve if you can, or at a valve upstream. Open a tap to drain the house.','Check the pipe type and size (15, 22 or 28 mm; copper, galvanised, HDPE) and choose the right valve and fittings.','Cut out or unscrew the old valve. Clean the pipe ends.','Fit the new valve with unions or compression joints so it can be changed later. Mind the flow arrow if there is one.','Support the pipe so the valve is not carrying its weight.','Open the water slowly and check all joints.','Test the new valve: close and open it, check it shuts completely.','Label the main stopcock and show the customer where it is.']}},

{id:'backflow-prevention',cat:'compliance,outdoor',title:'Backflow prevention (vacuum breakers, check valves)',kw:'backflow prevention cross connection vacuum breaker check valve double check valve air gap hose pipe pool irrigation geyser vacuum back siphonage terugvloei',sym:'what is backflow; where do I need a vacuum breaker; hose in a pool; irrigation backflow',sum:'Where backflow protection is needed and what to fit',
 repair:{head:'Backflow checklist',tools:['Camera','Spanner'],parts:[['Vacuum breaker','vacuum breaker'],['Non-return valve','non return valve'],['Hose bib with check','hose bib']],
  steps:['Look for any place where dirty water could be drawn back into the drinking-water pipe: hoses in buckets and pools, irrigation, boreholes, tanks, bidets, laboratory taps, car wash.','Use an air gap where possible: the best protection.','Fit a vacuum breaker or a check valve where an air gap is not possible; choose a device made for the risk level (check the standard).','Fit hose-bib vacuum breakers on outside taps.','Keep devices accessible for testing and replacement.','Never connect a borehole, rainwater system or a private source to the municipal supply.','Tell the customer what was fitted and why.'],
  sans:['SANS 10252-1 covers backflow prevention. Check the current edition and the municipal by-laws for the device required for each risk.']}},

{id:'no-water-at-all',cat:'emergency,pressure',title:'No water at all',kw:'no water supply no water at all taps dry water cut meter municipality tank empty pump off valve closed geen water droog kraan',sym:'taps give no water; water went off; no water in the whole house',sum:'Is it the municipality, the house or one fixture?',
 diagnose:{start:'q1',nodes:{
  q1:{q:'Do the neighbours also have no water?',opts:[['Yes','r_muni'],['No / not sure','q2']]},
  q2:{q:'Is water coming out of the outside tap or the meter side?',opts:[['No','q3'],['Yes, but not inside','r_inside']]},
  q3:{q:'Are the meter and the main stopcock open, and the meter box clean?',opts:[['Open, but no flow','r_block'],['Closed','r_closed']]},
  r_muni:{res:1,cause:'A municipal water outage',do:['Call or message the municipality water line or check their website.','Store water; do not run the geyser dry: switch off the geyser if the whole house is without water.'],call:'municipality'},
  r_inside:{res:1,cause:'A closed isolating valve inside or a fault after the main',do:['Open the valves one by one starting at the main.','Check the geyser and cistern valves.']},
  r_block:{res:1,cause:'Blocked meter strainer or a blocked pipe',do:['Close the stopcock, clean the strainer or filter.','If not fixed, call the municipality for the meter.'],call:'municipality'},
  r_closed:{res:1,cause:'The stopcock was closed',do:['Open it slowly, then open a tap to bleed air.','Switch the geyser on only when it is full.']}}},
 repair:{head:'Step-by-step',tools:['Torch','Meter key','Bucket'],parts:[['Stop tap','stop tap'],['Strainer','strainer']],
  steps:['Ask neighbours and check the municipal water page or call-line for outages.','Look at the meter: is it turning? Is the meter box valve open?','Open the main stopcock slowly and check for flow at an outside tap.','Open an outside tap, then the kitchen cold tap. If outside has water and inside does not, check the valves and the pipe inside.','Check the geyser isolating valve and the cistern valves.','Clean any strainer or filter that is blocked.','Bleed the air by opening taps after the supply returns.','Switch the geyser off until it is full again.']}},
{id:'hose-bib-garden-tap',cat:'outdoor,taps',title:'Garden tap (hose bib) leak or replacement',kw:'garden tap hose bib hosebib outside tap leaking replace vacuum breaker freeze wall plate tuinkraan buitekraan',sym:'garden tap drips; outside tap leaks from the handle; replace outside tap; hose bib wobbly',sum:'Fix or replace an outside tap, with backflow protection',
 repair:{warn:['Close the water before working. A hose left in water can siphon dirty water back into the supply: use a hose bib with a vacuum breaker or check valve.'],tools:['Spanners','PTFE tape','Pipe cutter','Screwdriver','Drill'],parts:[['Hose bib','hose bib'],['Garden tap','garden tap'],['Hose union','hose union'],['Vacuum breaker','vacuum breaker'],['Tap washer','tap washer']],
  steps:['Close the isolating valve to the outside tap and open the tap to drain the pipe.','Handle leak: undo the gland nut and replace the O-ring or packing, or the washer if it drips from the spout.','Replace the tap: unscrew the old tap from the wall plate or pipe; clean the thread.','Fit PTFE tape on the new tap thread and screw it in until firm; align the spout downward.','Fix the wall plate or clip so the tap cannot twist the pipe.','Fit a hose bib with a built-in check or a hose-connection vacuum breaker.','Open the supply, test for leaks, and check the pipe is lagged against frost.','Show the customer how to drain the pipe in freezing weather.'],
  sans:['SANS 10252-1: backflow protection on hose connections. Check the current edition.']}},

{id:'kitchen-sink-install',cat:'kitchen,install',title:'Kitchen sink and mixer installation',kw:'kitchen sink mixer install replace sink waste trap overflow stainless franke tap hole clamp silicone cutout sink bowl koskas gootsteen mixer',sym:'fit a new kitchen sink; replace a kitchen mixer; sink waste leaks; sink trap',sum:'Replace a sink, mixer, waste and trap neatly',
 install:{head:'Install checklist',warn:['Close the water and drain the pipes. Check the cabinet and top before cutting.'],tools:['Basin spanner','Silicone gun','Jigsaw (for cutout)','Spanners','Spirit level','Screwdrivers','Bucket'],parts:[['Sink','franke sink'],['Kitchen mixer','sink mixer'],['Sink waste','sink waste'],['Sink trap','sink trap'],['Flexi hose','flexi 350'],['Angle valve','angle valve'],['Silicone','silicone']],
  steps:['Isolate the water and disconnect the old mixer and waste. Remove the old sink and clean the top.','Check the cutout size against the new sink template and adjust.','Fit the mixer and the waste to the sink before lowering it in (easier on the bench).','Run a bead of sealant under the sink rim and fit the sink with the clamps from below.','Connect the flexi hoses to the angle valves (hot on the left). Tighten by hand plus a quarter turn.','Fit the trap and waste, with a fall to the drain. Fit a standpipe or tee for a dishwasher or washing machine where needed.','Open the angle valves slowly and check every joint dry for 10 minutes while the sink fills and drains.','Clean off excess sealant. Show the customer the isolating valves.'],
  sans:['SANS 10252-2: sink waste size, trap seal and fall. Check the current edition.']}},

{id:'coc-plumbing',cat:'compliance',title:'Certificate of Compliance (CoC) for plumbing and geysers',kw:'coc certificate of compliance plumbing coc electrical coc gas coc geyser insurance pirb licensed plumber sale of property municipality by-law certification sertifikaat',sym:'do I need a coc; geyser installation certificate; insurance wants a certificate; selling a house plumbing certificate',sum:'Which certificate applies, who may sign and what to keep',
 repair:{head:'Paperwork checklist',warn:['Only the right registered person may sign the right certificate. A plumber cannot sign an Electrical CoC and an electrician cannot sign a plumbing CoC.'],tools:['Camera','Job card','Copy of the certificate book'],parts:[['Safety valve','safety valve'],['Drip tray','geyser tray']],
  steps:['Plumbing CoC: a licensed (PIRB registered) plumber certifies plumbing work he did or inspected. Check the PIRB rules for what needs a certificate and where.','Electrical CoC: needed for geyser wiring, elements, thermostats and the DB circuit. A registered electrician issues it. A plumber may not.','Gas CoC: needed for gas installations. A registered gas installer issues it.','Take photos of the geyser installation: valves, drip tray and drain, wiring labels, pipes.','Keep a copy of the certificate and the job card for the customer. Note the date, the address and what was done.','Give the customer the originals and explain what each certificate covers.','Check the municipality and the insurer requirements. Some require a CoC for geyser replacements.'],
  sans:['SANS 10252-1 and SANS 10254 are used in plumbing and geyser installation compliance. Check current PIRB and municipal rules.']}},

{id:'sans-basics',cat:'compliance',title:'SANS basics for plumbers',kw:'sans standard 10252 10254 10400 10142 10087 241 460 explained building regulations nbr xa p r water supply drainage hot water installations norme standaard',sym:'which SANS applies; what is SANS 10252; which standard covers geysers; energy rule for hot water',sum:'A map of the standards that matter on most plumbing jobs',
 repair:{head:'Reading guide',tools:['Copy of the standard (buy or view at SABS)','Phone camera'],parts:[],
  steps:['SANS 10252-1: water supply and installations for buildings (pipes, valves, backflow, pressure, hot water).','SANS 10252-2: drainage installations (traps, falls, venting, access).','SANS 10254: installation of fixed electric storage water heaters (geysers): valves, drip tray and drain.','SANS 10400-P: drainage; SANS 10400-R: stormwater disposal; SANS 10400-XA: energy use in buildings (a share of hot water energy from sources other than direct electric resistance in new homes: check).','SANS 10142-1: wiring of premises (electrician and the Electrical CoC).','SANS 10087-1: LPG installations (gas installer).','SANS 241: drinking water quality.','SANS 460: copper tubes (wall thickness classes).','Standards change: always check the current edition before quoting a number. This app gives guide-only notes.'],
  sans:['This list is orientation only. SANS standards are copyrighted: read the full document before relying on a figure.']}},

{id:'job-handover-checklist',cat:'compliance,install',title:'Job handover checklist',kw:'handover checklist finish job sign off customer walkthrough photos leak test valves labelled cleanup invoice warranty handing over afhandeling kliënt',sym:'what to check before leaving site; final checks; hand over to customer',sum:'Finish every job the same way: test, photograph, explain, document',
 repair:{head:'Handover checklist',tools:['Phone camera','Job card','Invoice book'],parts:[],
  steps:['All joints are dry, tested under pressure, and clips are fixed.','All taps, valves and mixers work, with hot and cold on the correct sides.','Drains run freely, no gurgling or smell; traps hold water.','Geyser: full of water before switching on, safety valve and drain visible, tray and drain in place, thermostat setting explained, electrician CoC if done.','Isolating valves are accessible and the customer knows where the main stopcock is.','Photos taken: the finished work, any hidden pipes, valves and labels.','Rubble and offcuts are cleaned up, the area is tidy, and old parts are disposed of or given to the customer.','The customer has seen it working and knows what to do if there is a leak.','Invoice, warranty and certificate (if any) handed over.','Follow-up: send a WhatsApp message with the job summary.']}},

{id:'customer-advice-sheets',cat:'compliance',title:'Customer advice sheets (copy and send)',kw:'customer advice maintenance tips send whatsapp geyser care leaks water saving winter frost checklist advice sheet kliënt raad onderhoud',sym:'what to tell the customer; geyser maintenance advice; winter tips; how to find the main valve',sum:'Short advice messages you can copy to WhatsApp',
 repair:{head:'Advice you can send',tools:['WhatsApp'],parts:[],labels:{},
  steps:['GEYSER CARE: Know where the geyser isolator and the main water valve are. If water drips from the safety valve pipe more than a few drops, call us. Never switch the geyser on if the tank is empty.','GEYSER SETTINGS: A thermostat setting of around 60 degrees stops bacteria; use a mixing valve at taps if hot water is a scald risk (check the maker).','WINTER: Cover outdoor taps and exposed pipes. Drip a tap on a frosty night if pipes are exposed. Shut off and drain irrigation.','LEAK CHECK: Close all taps and look at the meter. If it moves, you have a leak. Check the toilets with food colour in the cistern.','DRAINS: Only toilet paper in the toilet. No cooking fat in the sink. Run water in unused drains once a week.','WATER SAVING: Fix drips quickly. Fit aerators and low-flow shower heads.','WHEN TO CALL: Burst pipe, no water, sewage overflow, gas smell, geyser leak.','Always keep the number of a registered electrician and a gas installer for geyser and gas problems.']}}
];
